function categoryIcon(slug){const clean=String(slug||'').toLowerCase().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');return '/assets/categories/'+(categoryImageMap[clean]||categoryImageMap.beauty)+'.webp'}
function publicCategoryNames(){const hidden=new Set(marketplaceCategories.filter(c=>c.visible===false).map(c=>c.name));return [...new Set([...marketplaceCategories.filter(c=>c.visible!==false).map(c=>c.name),...products.filter(p=>!p.bundle_definition).map(p=>p.category)].filter(n=>n&&!hidden.has(n)&&n!=='Bundles'))]}
function categoryImageFor(name){const meta=marketplaceCategories.find(c=>c.name===name);return safeImage(meta?.image_url)||categoryIcon(meta?.slug||meta?.icon||name)}
function renderCategoryPackDepartments(){const host=el('departments');if(!host)return;host.innerHTML=publicCategoryNames().map(name=>`<button type="button" class="dept market-circle-item" data-pick-category="${esc(name)}"><span class="dept-art market-circle-art"><img src="${categoryImageFor(name)}" alt="" width="96" height="96" loading="lazy"></span><strong>${esc(name)}</strong></button>`).join('')||'<div class="feature-empty">Categories are being set up.</div>'}
function productImageMarkup(p,alt=''){const src=safeImage(p.image_url),meta=marketplaceCategories.find(c=>c.name===p.category),fallback=categoryIcon(meta?.slug||meta?.icon||'beauty'),fallbackTag=`<img class="image-fallback" src="${fallback}" alt="" loading="lazy" ${src?'hidden':''}>`;return src?`<img class="product-photo" src="${src}" alt="${esc(alt)}" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false">${fallbackTag}`:fallbackTag}
function renderProductCategoryOptions(value=''){const field=el('prodCategory');if(!field)return;const categories=mergeMarketplaceCategories(marketplaceCategories);field.innerHTML='<option value="">Choose a category</option>'+categories.map(c=>`<option value="${esc(c.name)}">${esc(c.name)}</option>`).join('');if(value)field.value=value}
function categorySlug(name){return String(name||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,48)}
function renderCategoryAdmin(){const host=el('categoryAdminRows');if(!host)return;const icons=['electronics','womens-fashion','mens-fashion','home-living','beauty','health','grocery','sports','toys','books','automotive','jewellery'];host.innerHTML=marketplaceCategories.map((c,i)=>`<div class="category-admin-row" data-index="${i}"><img src="${categoryIcon(c.icon||c.slug)}" alt=""><input class="category-admin-name" maxlength="60" value="${esc(c.name)}" aria-label="Category name"><select class="category-admin-icon" aria-label="Category illustration">${icons.map(x=>`<option value="${x}" ${c.icon===x?'selected':''}>${x.replaceAll('-',' ')}</option>`).join('')}</select><button type="button" class="btn small category-remove" aria-label="Remove ${esc(c.name)}">Remove</button></div>`).join('')}
