async function boot(restoredSession=null){
 renderPackages();
 const {data,error}=restoredSession?{data:{session:restoredSession}}:await db.auth.getSession();if(error)throw error;session=data?.session||null;
 if(session){
  await shoppingAccount.identify(session);
  if(shoppingAccount.isCustomer){vendorPortal?.clear();profile=null;isAdmin=false;memberPackageCode=null;hasApprovedPackage=false;window.memberAccountBaseline=null;updateAuthNavigation();syncCheckoutIdentity();finishStartupRoute();await loadRequestedPage('shopping');await resumeShoppingCheckout();return;}
  const vendorAccess=await vendorPortal?.identify(session);
  if(vendorAccess?.vendor_only){profile=null;isAdmin=false;ownedBrands=[];memberPackageCode=null;hasApprovedPackage=false;updateAuthNavigation();if(['login','join','dashboard'].includes(location.hash.slice(1)))writeRoute('seller');finishStartupRoute();await loadRequestedPage(location.hash.slice(1)||'seller');return}
  const uid=session.user.id;
  const [member,roles,baseline,activation,admin]=await Promise.all([
   db.from('member_profiles').select('user_id,full_name,phone,country_code,gender,date_of_birth,terms_accepted_at,member_code,referral_code,sponsor_id,status,shopping_reward_mode,profile_photo_url,created_at,updated_at,transaction_pin_set_at').eq('user_id',uid).maybeSingle(),
   db.from('user_roles').select('role').eq('user_id',uid),db.rpc('my_account_baseline'),
   db.from('package_activations').select('package_code,activated_at').eq('member_id',uid).eq('status','approved').order('base_value',{ascending:false}).limit(1),
   db.rpc('current_user_is_admin')
  ]);
  if(session?.user.id!==uid)return;
  if(member.error||baseline.error||activation.error)throw member.error||baseline.error||activation.error;
  profile=member.data;isAdmin=admin.data===true||(roles.data||[]).some(x=>x.role==='admin');window.memberAccountBaseline=baseline.data||{};
  memberPackageCode=Object.hasOwn(window.memberAccountBaseline,'package_code')?window.memberAccountBaseline.package_code:activation.data?.[0]?.package_code||null;hasApprovedPackage=!!memberPackageCode;
  window.MioDashboard?.setTransactionPinConfigured(!!profile?.transaction_pin_set_at);updateSellerReferral();restoreMemberListView();
  el('walletSignIn').classList.add('hidden');syncCheckoutIdentity();
  if(window.memberAccountBaseline?.admin_provisioned&&profile&&!profile.terms_accepted_at){el('joinName').value=profile.full_name;el('joinPhone').value=profile.phone||'';el('joinCountry').value=profile.country_code||'PK';el('joinGender').value=profile.gender||'male';el('joinReferral').required=false;el('joinReferral').disabled=true;el('joinReferral').value='Assigned by administrator';}else{el('joinReferral').required=true;el('joinReferral').disabled=false;}
  window.MioDashboard?.setRewardPreference({eligible:hasApprovedPackage,mode:profile?.shopping_reward_mode||'PPV'});
  // Approved dual-role members keep the account destination chosen at sign-in.
 }
 updateAuthNavigation();window.MioCashHistory?.setIdentity(session?.user.id||null);window.MioWalletHub?.setIdentity(session?.user.id||null);finishStartupRoute();
 await loadRequestedPage(location.hash.slice(1)||'shop');await resumeShoppingCheckout();
}

