async function loadMaintenanceEarnings(uid){
 try{
  const rows=await fetchAll('maintenance_generation_payouts','id,maintenance_kind,generation,amount_mio,base_mio,rate,created_at',uid,'beneficiary_id');
  return rows.map(row=>({
   bonus_id:row.id,method:row.maintenance_kind+'_maintenance',generation:row.generation,
   payable_amount:row.amount_mio,qualifying_base:row.base_mio,rate:row.rate,status:'posted',created_at:row.created_at,
   source_kind:row.maintenance_kind==='monthly'?'Maintenance shopping':'Annual renewal'
  }));
 }catch(error){console.warn('Maintenance earnings unavailable',error);return []}
}
async function fetchAll(table,columns,uid,field){let rows=[],offset=0;for(;;){const {data,error}=await db.from(table).select(columns).eq(field,uid).order('id').range(offset,offset+999);if(error)throw error;rows.push(...(data||[]));if(!data||data.length<1000)return rows;offset+=1000}}
el('resetForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!session)throw Error('Open your password reset email first');if(el('resetPassword').value!==el('resetConfirm').value)throw Error('Passwords do not match');const {data:operator,error:roleError}=await db.rpc('current_user_is_admin');if(roleError)throw roleError;if(operator===true){const code=el('resetAuthenticatorCode').value.trim();if(!code)throw Error('Enter your operations account authenticator code');await verifyCode(code);const permit=await db.rpc('authorize_operator_password_change');if(permit.error)throw permit.error}const {error}=await db.auth.updateUser({password:el('resetPassword').value});if(error)throw error;form.reset();toast('Password updated');go(operator===true?'dashboard':'wallet')})});
