function renderAdminMembershipSummary(members,activations){
 const host=el('adminMembershipSummary');if(!host||!isAdmin)return;
 const latest=new Map;for(const row of activations)latest.set(row.member_id,row.package_code);networkMemberPackageById.clear();for(const [id,code] of latest)networkMemberPackageById.set(id,code);renderNetworkMemberPreview();
 const counts=new Map([['free',0],...packages.map(p=>[p.code,0])]);
 const enrolled=members.filter(m=>m.user_id!==session?.user.id).sort((a,b)=>(Date.parse(a.created_at)||0)-(Date.parse(b.created_at)||0)||String(a.user_id).localeCompare(String(b.user_id))).map((m,i)=>({...m,serial:i+1,package:latest.get(m.user_id)||'free'}));
 for(const member of enrolled)counts.set(member.package,(counts.get(member.package)||0)+1);
 const tiers=[['free','Free'],...packages.map(p=>[p.code,p.name]),...[...counts.keys()].filter(code=>code!=='free'&&!packages.some(p=>p.code===code)).map(code=>[code,planName(code)])];
 const activeMembers=enrolled.filter(m=>m.status==='active').length;host.innerHTML=`<div class="admin-primary-metrics"><button type="button" class="admin-vip-metric" data-member-tier="all" aria-expanded="false" aria-controls="adminMembershipDetails"><span class="metric-icon">♙</span><span>Total Registered Members</span><strong>${enrolled.length}</strong><b>→</b></button><button type="button" class="admin-vip-metric" data-member-tier="active" aria-expanded="false" aria-controls="adminMembershipDetails"><span class="metric-icon">♙</span><span>Active Members</span><strong>${activeMembers}</strong><b>→</b></button><button type="button" class="admin-vip-metric" data-workspace="binary-pool"><span class="metric-icon">⌘</span><span>Binary Shares</span><strong id="homeBinaryShares">—</strong><b>→</b></button><button type="button" class="admin-vip-metric" data-workspace="manager-program"><span class="metric-icon">♛</span><span>Manager Bonus</span><strong id="homeManagerBonus">—</strong><b>→</b></button><button type="button" class="admin-vip-metric" data-workspace="community-share"><span class="metric-icon">♙</span><span>Community Shares</span><strong id="homeCommunityShares">—</strong><b>→</b></button><button type="button" class="admin-vip-metric" data-workspace="package-report"><span class="metric-icon">◇</span><span>Package Activations</span><strong>${activations.length}</strong><b>→</b></button></div><div class="admin-mini-balances"><div><span>Company MIO Balance</span><strong id="homeCompanyMio">${el('adminMio')?.textContent||'—'} MIO</strong></div><div><span>Active Accounts</span><strong>${activeMembers}</strong></div><div><span>Packages Issued</span><strong>${activations.length}</strong></div></div><details class="admin-package-breakdown"><summary>View members by package</summary><div class="admin-membership-tiers">${tiers.map(([code,label])=>`<button type="button" class="admin-membership-tier" data-member-tier="${esc(code)}" aria-expanded="false" aria-controls="adminMembershipDetails"><span>${esc(label)}</span><b>${counts.get(code)||0}</b></button>`).join('')}</div></details><section id="adminMembershipDetails" class="admin-membership-details" hidden></section>`;
 let selected='all',page=1;
 const showMembers=()=>{
  if(!isAdmin||!session)return;
  const rows=enrolled.filter(m=>selected==='all'||selected==='active'&&m.status==='active'||m.package===selected).slice().reverse(),size=50,pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(Math.max(1,page),pages);
  const label=selected==='all'?'All members':selected==='active'?'Active members':tiers.find(t=>t[0]===selected)?.[1]||selected,details=host.querySelector('#adminMembershipDetails');details.hidden=false;
  const dayOf=m=>m.created_at?historyDay(m.created_at):'',dayCounts=new Map;for(const m of rows){const day=dayOf(m);dayCounts.set(day,(dayCounts.get(day)||0)+1)}let previousDay=null;
  const body=rows.slice((page-1)*size,page*size).map(m=>{const day=dayOf(m),heading=day!==previousDay?`<tr class="membership-date"><th colspan="6" scope="rowgroup">${day?esc(enrollmentDateLabel(day)):'Joining date unavailable'} · Members: ${dayCounts.get(day)}</th></tr>`:'';previousDay=day;return heading+`<tr><td>${m.serial}</td><td>${esc(m.member_code||'—')}</td><td>${esc(m.full_name||'Member unavailable')}</td><td>${esc(m.package==='free'?'Free':planName(m.package))}</td><td>${esc(m.status||'—')}</td><td>${day?esc(enrollmentDateLabel(day)):'—'}</td></tr>`}).join('');
  details.innerHTML=`<div class="membership-details-heading"><h3>${esc(label)} · ${rows.length} ${rows.length===1?'member':'members'}</h3><button type="button" class="btn small" data-member-close>Close</button></div><div class="table-wrap"><table class="compact-history"><thead><tr><th>S/No</th><th>MIO ID</th><th>Name</th><th>Package</th><th>Status</th><th>Joined</th></tr></thead><tbody>${body||'<tr><td colspan="6">No members in this category.</td></tr>'}</tbody></table></div>${pages>1?`<div class="package-report-pagination"><span>Page ${page} of ${pages}</span><button type="button" class="btn small" data-member-page="-1" ${page===1?'disabled':''}>Previous</button><button type="button" class="btn small" data-member-page="1" ${page===pages?'disabled':''}>Next</button></div>`:''}`;
  host.querySelectorAll('[data-member-tier]').forEach(button=>{const active=button.dataset.memberTier===selected;button.classList.toggle('active',active);button.setAttribute('aria-expanded',String(active))});
  details.querySelector('[data-member-close]').onclick=()=>{details.hidden=true;host.querySelectorAll('[data-member-tier]').forEach(button=>{button.classList.remove('active');button.setAttribute('aria-expanded','false')})};
  details.querySelectorAll('[data-member-page]').forEach(button=>button.onclick=()=>{page+=Number(button.dataset.memberPage);showMembers()});enhanceResponsiveTables(details);
 };
 host.querySelectorAll('[data-member-tier]').forEach(button=>button.onclick=()=>{selected=button.dataset.memberTier;page=1;showMembers()});
}
async function loadAdminMembershipSummary(){const uid=session?.user.id;const [members,activations]=await Promise.all([readDataset('member_profiles'),fetchPackageActivations()]);if(isAdmin&&session?.user.id===uid)renderAdminMembershipSummary(members,activations)}
async function loadOperationsMembers(){operationsMembers=await readDataset('member_profiles');await showOperationsMembers()}
async function loadOperationsReport(){if(!isAdmin)return;const {data,error}=await db.rpc('operations_report');if(error)throw error;if(!isAdmin||!el('operationsReport'))return;el('operationsReport').innerHTML=`<table><tbody>${Object.entries(data||{}).map(([key,value])=>`<tr><th>${esc(key.replaceAll('_',' '))}</th><td>${esc(typeof value==='object'?JSON.stringify(value):String(value))}</td></tr>`).join('')}</tbody></table>`}
el('refreshReport')?.addEventListener('click',()=>loadOperationsReport().catch(e=>toast(e.message)));
function exportText(rows,format){if(format==='json')return JSON.stringify(rows,null,2);const keys=[...new Set(rows.flatMap(row=>Object.keys(row)))];const cell=value=>{let text=value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};return [keys.map(cell).join(','),...rows.map(row=>keys.map(key=>cell(row[key])).join(','))].join('\r\n')}
el('exportForm')?.addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const dataset=el('exportDataset').value,format=el('exportFormat').value;const rows=await readDataset(dataset);const blob=new Blob([exportText(rows,format)],{type:format==='json'?'application/json':'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='mio-'+dataset+'-'+new Date().toISOString().slice(0,10)+'.'+format;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded: '+rows.length+' records')})});
document.addEventListener('submit',e=>{if(!e.target.matches('.inventory-form'))return;e.preventDefault();const form=e.target;submit(form,async()=>{const {error}=await db.rpc('update_seller_inventory',{p_product_id:form.dataset.id,p_price:Number(form.elements.price.value),p_stock:Number(form.elements.stock.value)});if(error)throw error;toast('Inventory saved. Price changes require listing review.');await loadSellerProducts(form.dataset.vendor);await loadCatalog()})});
document.addEventListener('click',e=>{const vm=e.target.closest('.view-mio');if(vm){const row=window.memberMioRows?.[Number(vm.dataset.index)];if(row)loadMioReceipt(row).catch(e=>toast(e.message));return}const vp=e.target.closest('.view-point');if(vp){const arr=vp.dataset.type==='PPV'?window.memberPpvRows:window.memberOtherPointRows;const row=arr?.[Number(vp.dataset.index)];if(row)showPointDetails(row);return}const ve=e.target.closest('.view-earning');if(ve){const row=window.memberBonusRows?.[Number(ve.dataset.index)];if(row)loadBonusReceipt(row).catch(e=>toast(e.message));return}const voucher=e.target.closest('.view-order-voucher');if(voucher){showOrderVoucher(voucher.dataset.id,voucher.dataset.voucherType||'customer');return}const cancel=e.target.closest('.cancel-order');if(cancel)submit({querySelector:()=>cancel},async()=>{const {error}=await db.rpc('cancel_unpaid_order',{p_order_id:cancel.dataset.id});if(error)throw error;toast('Order cancelled and stock restored');await loadMember();await loadCatalog()});const advance=e.target.closest('.advance-order');if(advance)submit({querySelector:()=>advance},async()=>{const {error}=await db.rpc('advance_order_status',{p_order_id:advance.dataset.id,p_status:advance.dataset.status});if(error)throw error;toast('Fulfillment status updated');await loadAdmin();if(advance.dataset.status==='confirmed')await showOrderVoucher(advance.dataset.id,'packing')})});
async function loadOfflineInstructions(){const {data,error}=await db.from('system_config').select('config_value').eq('config_key','OFFLINE_PAYMENT').is('effective_to',null).order('version',{ascending:false}).limit(1);if(error)throw error;const text=data?.[0]?.config_value?.instructions||'';el('offlinePaymentInstructions').textContent=text||'The company has not provided payment instructions yet. Do not send a payment until they are published.';el('premiumPurchaseForm').querySelector('button').disabled=!text}
el('premiumPurchaseForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{if(!session){go('login');throw Error('Sign in first')}const {error}=await db.rpc('request_offline_premium_purchase',{p_reference:el('premiumPaymentRef').value.trim(),p_details:el('premiumPaymentDetails').value.trim(),p_idempotency_key:idKey()});if(error)throw error;form.reset();toast('Payment submitted for verification. Platinum remains pending.');await loadPlatinumPurchases()})});
async function loadPlatinumPurchases(){if(!session)return;const uid=session.user.id;const {data,error}=await db.from('premium_purchase_requests').select('id,expected_pkr,payment_reference,status,review_note,created_at').eq('member_id',uid).order('created_at',{ascending:false}).limit(50);if(error)throw error;if(!session||session.user.id!==uid)return;el('premiumPurchaseHistory').innerHTML=data?.length?data.map(r=>`<div class="list-row"><div><strong>${esc(r.payment_reference)} · ${money(r.expected_pkr)}</strong><small>${new Date(r.created_at).toLocaleString()}${r.review_note?' · '+esc(r.review_note):''}</small></div><span class="pill">${esc(r.status)}</span></div>`).join(''):'<p>No offline Platinum purchase requests.</p>'}
async function loadPlatinumApprovals(){if(!isAdmin)return;const {data,error}=await db.from('premium_purchase_requests').select('*').eq('status','pending').order('created_at');if(error)throw error;if(!isAdmin)return;el('premiumPurchaseApprovals').innerHTML=data?.length?data.map(r=>`<form class="form premium-approval" data-id="${r.id}" data-amount="${r.expected_pkr}"><strong>${esc(operationsMembers.find(m=>m.user_id===r.member_id)?.member_code||r.member_id)} · ${money(r.expected_pkr)} · ${r.mio_amount} MIO</strong><p>${esc(r.payment_reference)}</p><p>${esc(r.payment_details)}</p><label>Decision<select name="decision"><option value="approve">Approve verified payment</option><option value="reject">Reject</option></select></label><label>Amount verified in company payment records (PKR)<input name="verified" type="number" min="0" step="0.01"></label><label>Verification or rejection note<textarea name="note" minlength="20" maxlength="2000" required></textarea></label><button class="btn primary">Verify & submit decision</button></form>`).join(''):'<p>No Platinum payments awaiting verification.</p>';el('premiumPurchaseApprovals').querySelectorAll('form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();submit(form,async()=>{const approve=form.elements.decision.value==='approve';await confirmSensitive((approve?'Approve':'Reject')+' this Platinum purchase. Expected payment: '+money(form.dataset.amount));const {error}=await db.rpc('review_offline_premium_purchase',{p_request_id:form.dataset.id,p_approve:approve,p_verified_pkr:approve?Number(form.elements.verified.value):null,p_note:form.elements.note.value.trim()});if(error)throw error;toast(approve?'Verified MIO purchase completed and Platinum activated':'Purchase request rejected');await loadMember()})}))}
el('offlineInstructionsForm').addEventListener('submit',e=>{e.preventDefault();submit(e.currentTarget,async()=>{const {error}=await db.rpc('set_offline_payment_instructions',{p_instructions:el('companyPaymentInstructions').value.trim()});if(error)throw error;toast('Company payment instructions published');await loadOfflineInstructions()})});

