 const target=el('networkCard'),uid=session?.user.id,turn=++sponsorNetworkRequest;
 if(!target)return;
 if(!uid){target.innerHTML='<div class="empty"><h3>Sign in to view your network</h3></div>';return;}
 target.setAttribute('aria-busy','true');target.innerHTML='<div class="empty" role="status"><h3>Loading your sponsor network…</h3></div>';
 try{const {data,error}=await db.rpc('my_direct_referrals');if(session?.user.id!==uid||turn!==sponsorNetworkRequest)return;if(error)throw error;
 const referrals=data||[];target.innerHTML=referrals.length?`<div class="list">${referrals.map(m=>`<div class="list-row"><div><strong>${esc(m.full_name)}</strong><small>${esc(m.member_code)} · ${new Date(m.created_at).toLocaleDateString()}</small></div><span class="pill">${esc(m.status)}</span></div>`).join('')}</div>`:hasApprovedPackage||isAdmin?'<div class="empty"><h3>No referrals yet</h3><p>Members who join through your referral will appear here.</p></div>':'<div class="empty"><h3>Your sponsor network</h3><p>No members have joined through your referral yet. Activate a plan to unlock team referral links.</p><button class="btn primary small" data-page="packages">View membership plans</button></div>';
 }catch(error){if(session?.user.id===uid&&turn===sponsorNetworkRequest)target.innerHTML='<div class="empty" role="alert"><h3>Network could not be loaded</h3><p>Please try again.</p><button class="btn" data-retry-sponsor-network>Retry</button></div>';console.warn('Sponsor network unavailable',error);
 }finally{if(turn===sponsorNetworkRequest)target.removeAttribute('aria-busy');}
