const communityPanel=panels.get('community-share');communityPanel.insertAdjacentHTML('beforeend',`<section class="community-admin-summary" id="communityAdminSummary" aria-live="polite"></section><div class="manager-admin-grid"><section class="card"><div class="card-head"><div><h3>Qualification & Gift rules</h3><p>Only actual qualified shares create gifts. Existing earned cohorts are never rewritten.</p></div></div><form id="communityRulesForm" class="card-body form"><label>Minimum package<select name="minimum_package"><option value="ADVANCED_2">Gold</option><option value="PREMIUM">Platinum</option></select></label><div class="rank-editor-grid"><label>Directs per actual share<input name="directs_per_share" type="number" min="1" required></label><label>DP per actual share<input name="dp_per_share" type="number" min="1" step=".0001" required></label><label>Gift after actual shares<input name="gift_every_actual_shares" type="number" min="1" required></label><label>Gift share quantity<input name="gift_share_quantity" type="number" min="1" required></label><label>Share validity cycles<input name="validity_cycles" type="number" min="1" max="120" required></label><label>Fund installments<input name="fund_installments" type="number" min="1" max="120" required></label></div><label><input name="enabled" type="checkbox"> Community Share enabled</label><button class="btn primary">Verify & save rules</button></form></section><section class="card"><div class="card-head"><div><h3>Add Community Fund</h3><p>The amount is reserved and released equally across the configured distribution cycles.</p></div></div><form id="communityFundForm" class="card-body form"><label>New fund amount (MIO)<input name="amount_mio" type="number" min=".00000001" step=".00000001" required></label><label>Fund source / note<textarea name="note" minlength="3" maxlength="500" required></textarea></label><button class="btn primary">Add 12-cycle fund</button></form></section></div><section class="card community-distribution-card"><div class="card-head"><div><h3>Manual distribution</h3><p>Each successful click advances exactly one audited cycle.</p></div><button type="button" class="btn primary" id="distributeCommunityShare">Distribute Next Cycle</button></div><div class="card-body"><div id="communityMembers" class="community-member-list"></div><div id="communityCycles" class="community-cycle-list"></div></div></section>`);
