let managerProgramVersion=0;
const managerRulesForm=managerPanel.querySelector('#managerRulesForm'),rankDefinitionForm=managerPanel.querySelector('#rankDefinitionForm');
rankDefinitionForm?.querySelector('button[type="submit"],button:not([type])')?.insertAdjacentHTML('beforebegin','<label class="badge-upload-field">Rank badge image<input id="leadershipRankBadgeFile" type="file" accept="image/jpeg,image/png,image/webp"><input name="badge_url" type="hidden"><span id="leadershipRankBadgePreview" class="badge-upload-preview">No image uploaded · text badge will be used</span></label>');
function rankBadgeMarkup({name,theme='emerald',badge_url=null,teamManager=false}={}){const url=safeImage(badge_url);return `<span class="rank-sticker ${teamManager?'rank-team-manager':'rank-'+esc(theme)} ${url?'rank-sticker-image':''}">${url?`<img src="${esc(url)}" alt="">`:teamManager?'◆':'★'}<span>${esc(name||'Rank')}</span></span>`}
function badgePreview(target,url,label){const host=el(target),safe=safeImage(url);if(!host)return;host.innerHTML=safe?`<img src="${esc(safe)}" alt="${esc(label)} badge preview"><span>${esc(label)} image ready</span>`:'No image uploaded · text badge will be used'}
async function uploadRankBadge(file,code){if(!['image/jpeg','image/png','image/webp'].includes(file?.type)||file.size>2097152)throw Error('Use a JPG, PNG or WebP badge up to 2 MB');const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=`${String(code||'rank').replace(/[^a-z0-9_-]/gi,'-').toLowerCase()}/${crypto.randomUUID()}.${ext}`;const {error}=await db.storage.from('rank-badges').upload(path,file,{contentType:file.type,cacheControl:'31536000',upsert:false});if(error)throw Error('Badge upload failed: '+error.message);return db.storage.from('rank-badges').getPublicUrl(path).data.publicUrl}
managerPanel.querySelector('#leadershipRankBadgeFile')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;const code=rankDefinitionForm.elements.rank_code.value.trim();if(!code){toast('Enter the rank code before uploading its badge');e.target.value='';return}e.target.disabled=true;try{const url=await uploadRankBadge(file,code);rankDefinitionForm.elements.badge_url.value=url;badgePreview('leadershipRankBadgePreview',url,rankDefinitionForm.elements.display_name.value||'Rank');toast('Rank badge uploaded. Save rank to publish it.')}catch(error){toast(error.message);e.target.value=''}finally{e.target.disabled=false}});
async function loadManagerProgram(){if(!isAdmin)return;const {data,error}=await db.rpc('admin_manager_program');if(error)throw error;const rules=data?.rules||{},form=el('managerRulesForm');managerProgramVersion=Number(rules.version)||0;for(const key of ['minimum_package','required_directs','required_direct_dp','required_tngp','required_qualified_lines','per_line_tngp','max_generations'])if(form.elements[key])form.elements[key].value=rules[key]??'';form.elements.track_rate.value=Number(rules.track_rate||0)*100;form.elements.network_rate.value=Number(rules.network_rate||0)*100;form.elements.enabled.checked=rules.enabled!==false;const ranks=data?.ranks||[];el('leadershipRanks').innerHTML=ranks.map(r=>`<div class="rank-definition-row"><span class="rank-sticker rank-${esc(r.badge_theme)}">★ ${esc(r.display_name)}</span><span>${Number(r.left_brp).toFixed(0)} L BRP</span><span>${Number(r.right_brp).toFixed(0)} R BRP</span><span>${r.direct_left}/${r.direct_right} directs</span><span>${Number(r.required_dp).toFixed(0)} DP</span><span>${r.active?'Active':'Disabled'}</span><button type="button" class="btn small rank-edit-button" data-edit-rank="${esc(r.rank_code)}">Edit</button></div>`).join('');el('leadershipRanks').dataset.rows=JSON.stringify(ranks);const pending=data?.pending||[];el('managerPending').innerHTML=pending.length?pending.map(r=>`<div class="list-row"><div><strong>${esc(r.full_name)}</strong><small>${esc(r.member_code)}</small></div><span>${Number(r.mtp).toFixed(4)} MTP · ${Number(r.mngp).toFixed(4)} MNGP</span></div>`).join(''):'<p>No undistributed Manager points.</p>'}
const loadManagerProgramBase=loadManagerProgram;
loadManagerProgram=async function(){await loadManagerProgramBase();if(!isAdmin)return;const {data,error}=await db.rpc('admin_manager_program');if(error)throw error;const ranks=data?.ranks||[],summary=data?.summary||{};el('leadershipRanks').innerHTML=ranks.map(r=>`<div class="rank-definition-row">${rankBadgeMarkup({name:r.display_name,theme:r.badge_theme,badge_url:r.badge_url})}<span>${Number(r.left_brp).toFixed(0)} L BRP</span><span>${Number(r.right_brp).toFixed(0)} R BRP</span><span>${r.direct_left}/${r.direct_right} directs</span><span>${Number(r.required_dp).toFixed(0)} DP</span><span>${r.active?'Active':'Disabled'}</span><button type="button" class="btn small rank-edit-button" data-edit-rank="${esc(r.rank_code)}">Edit</button></div>`).join('');el('leadershipRanks').dataset.rows=JSON.stringify(ranks);const snapshot=el('adminManagerSnapshot');if(snapshot)snapshot.innerHTML=`<span class="admin-report-tag">MB</span><strong>Manager Bonus</strong><small>Generated <b>${Number(summary.total_generated_mio||0).toFixed(4)} MIO</b> · Wallets <b>${Number(summary.wallet_distributed_mio||0).toFixed(4)}</b> · In management <b>${Number(summary.management_pending_mio||0).toFixed(4)}</b></small><b>Open manager control <span aria-hidden="true">→</span></b>`;const detail=el('managerFinancialSummary');if(detail)detail.innerHTML=`<div><span>Total bonus generated</span><strong>${Number(summary.total_generated_mio||0).toFixed(4)} MIO</strong></div><div><span>Distributed to wallets</span><strong>${Number(summary.wallet_distributed_mio||0).toFixed(4)} MIO</strong></div><div><span>Pending in management</span><strong>${Number(summary.management_pending_mio||0).toFixed(4)} MIO</strong></div><div><span>Managers pending</span><strong>${Number(summary.pending_manager_count||0)}</strong></div><div><span>Manager Track Points</span><strong>${Number(summary.total_mtp||0).toFixed(4)}</strong></div><div><span>Manager Network Points</span><strong>${Number(summary.total_mngp||0).toFixed(4)}</strong></div>`;return data};
let superMemberProgramVersion=0;
async function loadSuperMemberProgram(){if(!isAdmin)return;const {data,error}=await db.rpc('admin_super_member_program');if(error)throw error;const rules=data?.rules||{},summary=data?.summary||{},form=el('superMemberRulesForm');superMemberProgramVersion=Number(rules.version)||0;if(form){for(const key of ['minimum_package','required_directs','required_direct_dp','ppv_to_mio'])form.elements[key].value=rules[key]??'';form.elements.reward_rate.value=Number(rules.reward_rate||0)*100;form.elements.enabled.checked=rules.enabled!==false;form.elements.self_shopping.checked=rules.self_shopping!==false;form.elements.affiliate_shopping.checked=rules.affiliate_shopping!==false}el('superMemberAdminState').textContent=rules.enabled===false?'Programme paused':`${Number(rules.reward_rate||0)*100}% PPV · ${Number(rules.ppv_to_mio||0)} MIO per PPV`;el('superMemberAdminSummary').innerHTML=`<div><span>Qualified</span><strong>${Number(summary.qualified_members||0)}</strong></div><div><span>Benefits active</span><strong>${Number(summary.active_members||0)}</strong></div><div><span>Total credited</span><strong>${Number(summary.total_reward_mio||0).toFixed(4)} MIO</strong></div><div><span>Self shopping</span><strong>${Number(summary.self_reward_mio||0).toFixed(4)} MIO</strong></div><div><span>Affiliate shopping</span><strong>${Number(summary.affiliate_reward_mio||0).toFixed(4)} MIO</strong></div>`;const members=data?.members||[];el('superMemberMembers').innerHTML=members.length?members.map(m=>`<div class="super-member-admin-row"><div><strong>${esc(m.full_name)}</strong><small>${esc(m.member_code)} · Qualified ${new Date(m.qualified_at).toLocaleDateString()}</small>${m.suspension_note?`<small class="warning">${esc(m.suspension_note)}</small>`:''}</div><span>${Number(m.total_reward_mio||0).toFixed(4)} MIO</span><button type="button" class="btn small" data-super-member-id="${esc(m.member_id)}" data-super-member-active="${m.active?'false':'true'}">${m.active?'Pause benefit':'Reactivate'}</button></div>`).join(''):'<p>No member has qualified yet.</p>';const rewards=data?.recent_rewards||[];el('superMemberRewards').innerHTML=rewards.length?`<div class="history-table-scroll"><table class="compact-history"><thead><tr><th>Date</th><th>Member</th><th>Order</th><th>Benefit</th><th>PPV</th><th>MIO</th></tr></thead><tbody>${rewards.map(r=>`<tr><td>${esc(pkDateTime(r.created_at))}</td><td><strong>${esc(r.full_name)}</strong><small>${esc(r.member_code)}</small></td><td class="code">${esc(r.order_code)}</td><td>${r.reward_kind==='affiliate_shopping'?'Affiliate shopping':'Self shopping'}</td><td>${Number(r.eligible_ppv).toFixed(4)}</td><td class="amount-positive">${Number(r.amount_mio).toFixed(4)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No Super Member reward has been posted yet.</p>';const snapshot=el('adminSuperMemberSnapshot');if(snapshot)snapshot.innerHTML=`<span class="admin-report-tag">SM</span><strong>Super Member</strong><small><b>${Number(summary.active_members||0)}</b> active · <b>${Number(summary.total_reward_mio||0).toFixed(4)} MIO</b> credited</small><b>Open programme <span aria-hidden="true">→</span></b>`;return data}
let communityProgramVersion=0;
async function loadCommunityProgram(){if(!isAdmin)return;const {data,error}=await db.rpc('admin_community_share_program');if(error)throw error;const rules=data?.rules||{},form=el('communityRulesForm');communityProgramVersion=Number(rules.version)||0;for(const key of ['minimum_package','directs_per_share','dp_per_share','gift_every_actual_shares','gift_share_quantity','validity_cycles','fund_installments'])if(form?.elements[key])form.elements[key].value=rules[key]??'';if(form)form.elements.enabled.checked=rules.enabled!==false;const summary=el('communityAdminSummary');if(summary)summary.innerHTML=`<div><span>Next cycle</span><strong>${Number(data?.next_cycle||1)}</strong></div><div><span>Due pool</span><strong>${Number(data?.due_pool_mio||0).toFixed(4)} MIO</strong></div><div><span>Active shares</span><strong>${Number(data?.active_total_shares||0)}</strong><small>${Number(data?.active_actual_shares||0)} actual · ${Number(data?.active_gift_shares||0)} gift</small></div><div><span>Reserved</span><strong>${Number(data?.reserved_mio||0).toFixed(4)} MIO</strong></div><div><span>Released</span><strong>${Number(data?.released_mio||0).toFixed(4)} MIO</strong></div>`;const members=data?.members||[];el('communityMembers').innerHTML=members.length?`<div class="community-admin-heading"><strong>Eligible members for cycle ${Number(data.next_cycle||1)}</strong><span>${members.length} member(s)</span></div>${members.map(m=>`<div class="list-row"><div><strong>${esc(m.full_name)}</strong><small>${esc(m.member_code)}</small></div><span>${Number(m.actual_shares)} actual + ${Number(m.gift_shares)} gift = <b>${Number(m.total_shares)}</b></span></div>`).join('')}`:'<p>No active Community Shares for the next cycle.</p>';const cycles=data?.cycles||[];el('communityCycles').innerHTML=cycles.length?`<h4>Distribution history</h4>${cycles.slice(0,12).map(c=>`<div class="list-row"><div><strong>Cycle ${Number(c.cycle_number)}</strong><small>${new Date(c.created_at).toLocaleString()}</small></div><span>${Number(c.fund_pool_mio).toFixed(4)} MIO · ${Number(c.total_active_shares)} shares · ${Number(c.member_count)} members</span></div>`).join('')}`:'<p>No Community Share distribution has been completed.</p>';const snapshot=el('adminCommunitySnapshot');if(snapshot)snapshot.innerHTML=`<span class="admin-report-tag">CS</span><strong>Global Community Share</strong><small>Cycle <b>${Number(data?.next_cycle||1)}</b> · Due <b>${Number(data?.due_pool_mio||0).toFixed(4)} MIO</b> · Active <b>${Number(data?.active_total_shares||0)}</b> shares</small><b>Open community control <span aria-hidden="true">→</span></b>`;return data}
const loadMasterDashboardBase=loadMasterDashboard;
loadMasterDashboard=async function(...args){const result=await loadMasterDashboardBase(...args);if(isAdmin){await Promise.all([loadManagerProgram(),loadSuperMemberProgram(),loadCommunityProgram()]);refreshAdminControlSummaries();await window.networkReporting?.refresh()}return result};
const loadManagerProgramSummary=loadManagerProgram;
loadManagerProgram=async function(...args){const data=await loadManagerProgramSummary(...args);if(el('homeManagerBonus'))el('homeManagerBonus').textContent=Number(data?.summary?.management_pending_mio||0).toFixed(2)+' MIO';if(adminFinanceSnapshot)renderAdminFinanceHighlights(adminFinanceSnapshot);return data};
const loadCommunityProgramSummary=loadCommunityProgram;
loadCommunityProgram=async function(...args){const data=await loadCommunityProgramSummary(...args);if(el('homeCommunityShares'))el('homeCommunityShares').textContent=String(Number(data?.active_total_shares||0));if(adminFinanceSnapshot)renderAdminFinanceHighlights(adminFinanceSnapshot);return data};
managerRulesForm?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await confirmSensitive('Update Team Manager qualification and bonus rules');const rules=Object.fromEntries(new FormData(form));rules.enabled=form.elements.enabled.checked;rules.track_rate=Number(rules.track_rate)/100;rules.network_rate=Number(rules.network_rate)/100;const {error}=await db.rpc('admin_set_team_manager_rules',{p_rules:rules,p_expected_version:managerProgramVersion});if(error)throw error;toast('Team Manager rules saved');await loadManagerProgram()})});
superMemberPanel.querySelector('#superMemberRulesForm')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await confirmSensitive('Update Super Member qualification and PPV-to-MIO benefit rules');const rules=Object.fromEntries(new FormData(form));rules.enabled=form.elements.enabled.checked;rules.self_shopping=form.elements.self_shopping.checked;rules.affiliate_shopping=form.elements.affiliate_shopping.checked;rules.reward_rate=Number(rules.reward_rate)/100;const {error}=await db.rpc('admin_set_super_member_rules',{p_rules:rules,p_expected_version:superMemberProgramVersion});if(error)throw error;toast('Super Member rules saved');await loadSuperMemberProgram()})});
superMemberPanel.querySelector('#superMemberMembers')?.addEventListener('click',e=>{const button=e.target.closest('[data-super-member-id]');if(!button)return;submit({querySelector:()=>button},async()=>{const active=button.dataset.superMemberActive==='true',note=active?null:prompt('Reason for pausing this Super Member benefit:','Administrative review')||'Administrative review';await confirmSensitive(`${active?'Reactivate':'Pause'} this Super Member benefit`);const {error}=await db.rpc('admin_set_super_member_status',{p_member_id:button.dataset.superMemberId,p_active:active,p_note:note});if(error)throw error;toast(active?'Super Member benefit reactivated':'Super Member benefit paused');await loadSuperMemberProgram()})});
communityPanel.querySelector('#communityRulesForm')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await confirmSensitive('Update Global Community Share qualification, gift and cycle rules');const rules=Object.fromEntries(new FormData(form));rules.enabled=form.elements.enabled.checked;const {error}=await db.rpc('admin_set_community_share_rules',{p_rules:rules,p_expected_version:communityProgramVersion});if(error)throw error;toast('Community Share rules saved');await loadCommunityProgram()})});
communityPanel.querySelector('#communityFundForm')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{const amount=Number(form.elements.amount_mio.value);await confirmSensitive(`Reserve ${amount.toFixed(4)} MIO as a multi-cycle Global Community Share fund`);const {data,error}=await db.rpc('admin_add_community_fund',{p_amount_mio:amount,p_note:form.elements.note.value.trim(),p_idempotency_key:idKey()});if(error)throw error;form.reset();toast(`Community fund added · ${Number(data?.installment_mio||0).toFixed(4)} MIO per cycle`);await loadCommunityProgram()})});
const distributeCommunityShare=communityPanel.querySelector('#distributeCommunityShare');
distributeCommunityShare?.addEventListener('click',()=>submit({querySelector:()=>distributeCommunityShare},async()=>{await confirmSensitive('Distribute the next Global Community Share cycle now. This permanently credits all active shares and advances the cycle counter by one.');const {data,error}=await db.rpc('admin_distribute_community_share',{p_idempotency_key:idKey()});if(error)throw error;toast(`Community cycle ${Number(data?.cycle_number||0)} distributed · ${Number(data?.distributed_mio||0).toFixed(4)} MIO`);await loadCommunityProgram();await loadMasterDashboard()}));
rankDefinitionForm?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;submit(form,async()=>{await confirmSensitive('Save this leadership rank definition');const rank=Object.fromEntries(new FormData(form));rank.active=form.elements.active.checked;const {error}=await db.rpc('admin_upsert_leadership_rank',{p_rank:rank});if(error)throw error;form.reset();form.elements.active.checked=true;badgePreview('leadershipRankBadgePreview',null,'Rank');toast('Leadership rank saved');await loadManagerProgram()})});
