async function loadMaintenanceAdmin(monthly){
 const member=session?.user.id,host=monthly?maintenanceAdmin:annualMaintenanceAdmin;
 host.textContent='Loading maintenance rules…';
 const {data,error}=await maintenanceRpc('admin_maintenance_program');
 if(!isAdmin||session?.user.id!==member)return;
 if(error){host.textContent='Maintenance settings unavailable.';return}
 const rules=data.rules;
 if(monthly)setTimeout(()=>loadCountryMaintenanceControls().catch(e=>toast(e.message)),0);
 const packages=[['BASIC_1','Starter'],['BASIC_2','Basic'],['ADVANCED_1','Silver'],['ADVANCED_2','Gold'],['PREMIUM','Platinum']];
 const percent=rate=>Number((Number(rate||0)*100).toFixed(6));
 host.innerHTML=`${monthly?'<section id="countryMaintenanceControls" class="country-maintenance-controls"></section>':''}<h3>${monthly?'Monthly qualification and generation rates':'Annual maintenance rules'}</h3>
  <p>${Number(monthly?data.monthly_active:data.annual_active)} active members</p>
  <form class="form">
  ${monthly?`<label><input name="enabled" type="checkbox" ${rules.enabled?'checked':''}> Enable maintenance program</label>
  <div class="table-wrap"><table><thead><tr><th>Package</th><th>Required PPV</th><th>Bonus generations</th></tr></thead><tbody>
  ${packages.map(([code,label])=>`<tr><th scope="row">${label}</th><td><input aria-label="${label} required PPV" name="ppv_${code}" type="number" min="1" value="${Number(rules.monthly_ppv[code])}" required></td><td><input aria-label="${label} bonus generations" name="levels_${code}" type="number" min="1" max="10" value="${Number(rules.monthly_levels[code])}" required></td></tr>`).join('')}
  </tbody></table></div>
  <fieldset><legend>Generation payout rates</legend><p>Each rate applies to the order PPV. The bonus recipient’s package sets their generation limit.</p>
  <div class="maintenance-rate-grid">${Array.from({length:10},(_,i)=>`<label>Generation ${i+1} (%)<input name="generation_${i+1}" type="number" min="0" max="100" step="0.000001" value="${percent(rules.monthly_rates[i])}" required></label>`).join('')}</div>
  <p><output aria-live="polite" name="rate_total"></output></p></fieldset>`:
  `<div class="maintenance-rate-grid"><label>Annual fee (MIO)<input name="annual_fee_mio" type="number" min="0.0001" step="0.0001" value="${Number(rules.annual_fee_mio)}" required></label><label>Company fee (%)<input name="annual_company_rate" type="number" min="0" max="100" step="0.000001" value="${percent(rules.annual_company_rate)}" required></label></div><label>Annual generation rates (% of the full fee, comma separated)<input name="annual_rates" value="${rules.annual_rates.map(percent).join(', ')}" required></label><p class="helper">Default: company 50%, generations 35%, 10%, 5%. Total must be 100% or less; unused amount is recorded as leftover.</p>`}
  <button class="btn primary" type="submit">Save ${monthly?'monthly':'annual'} maintenance rules</button></form>`;
 const form=host.querySelector('form'),inputs=form.elements;
 const monthlyRates=()=>Array.from({length:10},(_,i)=>Number(inputs['generation_'+(i+1)].value)/100);
 const updateTotal=()=>{
  const total=percent(monthlyRates().reduce((sum,rate)=>sum+rate,0));
  inputs.rate_total.value=`Configured: ${total}% · Maximum: 100%`;
  inputs.generation_10.setCustomValidity(total>100?'Generation rates must total 100% or less.':'');
 };
 if(monthly){form.addEventListener('input',updateTotal);updateTotal();enhanceResponsiveTables(host)}
 form.addEventListener('submit',e=>{
  e.preventDefault();
  submit(form,async()=>{
   const next={...rules};
   if(monthly){
    next.enabled=inputs.enabled.checked;
    next.monthly_rates=monthlyRates();
    next.monthly_ppv=Object.fromEntries(packages.map(([code])=>[code,Number(inputs['ppv_'+code].value)]));
    next.monthly_levels=Object.fromEntries(packages.map(([code])=>[code,Number(inputs['levels_'+code].value)]));
   }else{next.annual_fee_mio=Number(inputs.annual_fee_mio.value);next.annual_company_rate=Number(inputs.annual_company_rate.value)/100;next.annual_rates=inputs.annual_rates.value.split(',').map(value=>{
    const rate=Number(value);
    if(!value.trim()||!Number.isFinite(rate)||rate<0||rate>100)throw Error('Enter valid percentages separated by commas.');
    return rate/100;
   });}
   await confirmSensitive('Save maintenance qualification rules and generation payout rates.');
   const {error}=await maintenanceRpc('admin_set_maintenance_rules',{p_rules:next,p_expected_version:rules.version});
   if(error)throw error;
   toast('Maintenance rules saved.');
   await loadMaintenanceAdmin(monthly);
  });
 });
}
