async function loadCommissionReport(){const uid=session?.user.id;const [earnings,allocs]=await Promise.all([db.rpc('vendor_company_earnings'),db.from('commission_allocations').select('*').order('created_at',{ascending:false}).limit(300)]);const failure=[earnings,allocs].find(r=>r.error)?.error;if(failure)throw failure;if(!isAdmin||session?.user.id!==uid)return;const previousVendor=el('commissionVendor').value;el('commissionVendor').innerHTML='<option value="">Select a vendor first</option>'+adminVendorRows.map(v=>`<option value="${v.id}">${esc(v.business_name)} · ${(Number(v.commission_rate)*100).toFixed(2)}% agreed</option>`).join('');el('commissionVendor').value=adminVendorRows.some(v=>v.id===previousVendor)?previousVendor:'';renderSplitInputs();el('vendorCompanyEarnings').innerHTML='<h3>Company earnings from vendors</h3><p>Confirmed sales only. Company share is 5% of merchandise sale; shipping is excluded.</p>'+((earnings.data||[]).map(v=>`<div class="list-row"><strong>${esc(v.business_name)}</strong><span>${money(v.company_earnings_pkr)}</span></div>`).join('')||'<p>No confirmed sales yet.</p>');const rows=allocs.data||[];el('commissionReport').innerHTML=`<h3>Commission records</h3><p>Earned: ${money(rows.filter(r=>r.status==='earned').reduce((n,r)=>n+Number(r.amount_pkr),0))} · Held: ${money(rows.filter(r=>r.status==='held').reduce((n,r)=>n+Number(r.amount_pkr),0))} · Showing latest ${rows.length} records. Export for complete totals.</p>`+(rows.length?rows.map(r=>`<div class="list-row"><div><strong>${esc(splitLabels[r.share_kind])} · ${money(r.amount_pkr)}</strong><small>${esc(r.status)} · ${esc(operationsMembers.find(m=>m.user_id===r.beneficiary_id)?.member_code||r.beneficiary_id||'Recipient not identified')} · Order item ${esc(r.order_item_id)}</small>${r.payment_reference?`<small>${esc(r.payment_reference)}</small>`:''}</div>${r.status==='held'&&!['company','buyer_discount','network_rewards','unallocated'].includes(r.share_kind)?`<form class="resolve-commission form" data-id="${r.id}"><label>Verified recipient member code<input name="code" required></label><label>How was this recipient verified?<textarea name="reason" minlength="20" required></textarea></label><button class="btn small">Verify & release held share</button></form>`:r.status==='earned'&&!['company','buyer_discount','network_rewards','unallocated'].includes(r.share_kind)?`<form class="commission-payment form" data-id="${r.id}"><label>Actual bank payment reference<input name="reference" minlength="10" required></label><button class="btn small">Verify & mark paid</button></form>`:''}</div>`).join(''):'<p>Records appear after confirmed vendor purchases.</p>')}
async function loadSellerAgreement(){updateSellerReferral();if(!session)return;const uid=session.user.id;const {data,error}=await db.from('vendor_applications').select('*').eq('applicant_user_id',session.user.id).order('created_at',{ascending:false}).limit(1);if(error)throw error;if(session?.user.id!==uid)return;const a=data?.[0];el('sellerAgreement').innerHTML=a?`<article class="review-card"><h3>Your application: ${esc(a.business_name)}</h3><p>Status: ${esc(a.status)}</p>${countryBadge(a.country_code)}${a.offered_commission!=null?`<p>Company offer: ${(a.offered_commission*100).toFixed(2)}% of product sale price.</p><p>${esc(a.terms_note)}</p>${a.agreement_accepted_at?'<p>Terms accepted. The company can now approve your store.</p>':a.status==='pending'?`<button class="btn primary accept-terms" data-id="${a.id}">Accept this commission and terms</button>`:''}`:'<p>The company will send its final commission offer here.</p>'}</article>`:'';el('sellerForm').classList.toggle('hidden',!!a);}
async function loadOwnedBrands(){if(!session)return;const uid=session.user.id;let q=db.from('vendors').select('id,business_name,status,owner_user_id,is_company_owned,contact_email,contact_phone,commission_rate,country_code').eq('status','active');if(!isAdmin)q=q.eq('owner_user_id',session.user.id);const {data,error}=await q.order('created_at');if(error)throw error;if(session?.user.id!==uid)return;ownedBrands=data||[];organizeSellerWorkspace();updateAuthNavigation();if(!ownedBrands.some(v=>v.id===selectedVendor))selectedVendor=ownedBrands[0]?.id||null;for(const id of ['productVendor','sellerBrand']){el(id).innerHTML=ownedBrands.map(v=>`<option value="${v.id}">${esc(v.business_name)}</option>`).join('');el(id).value=selectedVendor||''}el('sellerProducts').classList.toggle('hidden',!selectedVendor);el('sellerNav').classList.add('hidden');if(selectedVendor){await loadSellerProducts(selectedVendor);await loadSellerAccount(selectedVendor)}el('vendorWithdrawalForm').classList.toggle('hidden',!ownedBrands.find(v=>v.id===selectedVendor&&v.owner_user_id===session.user.id))}
