function retailPriceLabel(p){const list=Number(p.compare_at_price_pkr),sale=Number(p.price_pkr);if(!Number.isFinite(list)||list<=sale||sale<=0)return '';const saved=Math.round((list-sale)*100)/100;return `<del class="original-price">${money(list)}</del> <small class="sale-saving">${Math.floor((list-sale)*100/list)}% off · Save ${money(saved)}</small>`}
