function pkDateTime(value){if(!value||!Number.isFinite(Date.parse(value)))return 'Date unavailable';return new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:true}).format(new Date(value))+' PKT'}
function ecommerceSource(row){return {name:row.source_name||(row.record_type==='maintenance_payout'?'Annual renewal':'Guest customer'),code:row.source_code||(row.record_type==='maintenance_payout'?'Maintenance payout':'Guest order')}}
function shoppingKind(order,meta){return meta?.maintenance?.has(order.id)?'maintenance':meta?.payments?.get(order.id)?.checkout_mode==='SHOPPING_POINTS'?'shopping_points':'normal'}
function shoppingLabel(kind){return ({maintenance:'Monthly maintenance',shopping_points:'Shopping Points shopping',normal:'Normal shopping'})[kind]||'Normal shopping'}
function shoppingPayment(order,allocation){if(!allocation&&Number(order.customer_advance_pkr)>0)return money(order.customer_advance_pkr)+' advance paid · '+money(order.cod_due_pkr)+' COD';if(!allocation)return order.payment_method==='COD'?'Cash on Delivery':order.payment_status==='confirmed'?'Paid in advance':'Payment pending';const parts=[];if(Number(allocation.shopping_points_used)>0)parts.push(Number(allocation.shopping_points_used).toFixed(2)+' Shopping Points');if(Number(allocation.cash_mio_used)>0)parts.push(Number(allocation.cash_mio_used).toFixed(4)+' Cash Wallet MIO');if(Number(allocation.cod_due_pkr)>0)parts.push(money(allocation.cod_due_pkr)+' COD');return parts.join(' · ')||'Payment pending'}
