document.addEventListener('click',e=>{const button=e.target.closest('[data-shopping-kind]');if(!button)return;const host=el('ordersTable');if(!host?.contains(button))return;const kind=button.dataset.shoppingKind;host.querySelectorAll('[data-shopping-kind]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});host.querySelectorAll('[data-order-kind]').forEach(row=>{row.hidden=kind!=='all'&&row.dataset.orderKind!==kind})});
function earningRows(){return window.memberBonusRows||[]}
