function sourceAmount(source){const teamMethods=['direct','generation','binary_pool_share','single_line','team_manager'];const bonus=earningRows().filter(x=>(source==='all'||(source==='team_bonus'?teamMethods.includes(x.method):x.method===source))&&x.status==='posted').reduce((n,x)=>n+Number(x.payable_amount||0),0);const eco=(window.memberEcommerceRows||[]).filter(x=>x.status==='posted'&&(source==='ecommerce')).reduce((n,x)=>n+Number(x.amount||0),0);const opening=(window.memberOpeningRows||[]).filter(r=>source==='all'||(source==='team_bonus'?teamMethods.includes(r.category==='manager'?'team_manager':r.category):(r.category==='manager'?'team_manager':r.category)===source)).reduce((sum,r)=>sum+Number(r.amount||0),0);return bonus+eco+opening}
function earningTrace(row){const value=row?.calculation_trace||{};if(typeof value!=='string')return value;try{return JSON.parse(value)}catch{return {}}}
function earningMobileLedger(rows,source='all'){
 if(!rows.length)return '<div class="earning-mobile-empty"><span>◎</span><h3>No matching earnings</h3><p>Try another date range or earning type.</p></div>';
 const sorted=[...rows].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),groups=new Map();for(const row of sorted){const day=historyDay(row.created_at);if(!groups.has(day))groups.set(day,[]);groups.get(day).push(row)}
 const presentation=row=>{const trace=earningTrace(row),eco=!!row.reward_kind,method=eco?'ecommerce':row.method,amount=earningAmount(row),held=isHeldEarning(row),time=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Karachi',hour:'2-digit',minute:'2-digit',hour12:true}).format(new Date(row.created_at))+' PKT',rate=row.rate==null?'':(Number(row.rate)*100).toFixed(2).replace(/\.00$/,'')+'%',member=row.source_name||(method==='binary_pool_share'?'Binary share pool':'Member unavailable'),code=row.source_code||'',pkg=row.source_package_code?planName(row.source_package_code):'',base=Number(row.qualifying_base||0).toFixed(2),level=Number(row.generation||1);let icon='E',title=eco?ecommerceKind(row.reward_kind):bonusDisplayLabel(row),subtitle=[member,code].filter(Boolean).join(' · '),detail='Recorded earning';
  if(method==='direct'){icon=title.startsWith('Welcome')?'W':'D';detail=['Direct',base+' DP',rate].filter(Boolean).join(' · ');subtitle=[member,code,pkg].filter(Boolean).join(' · ')}
  else if(method==='generation'){icon='G'+level;detail=['Level '+level,base+' GP',rate].filter(Boolean).join(' · ');subtitle=[member,code,pkg].filter(Boolean).join(' · ')}
  else if(method==='binary_pool_share'){const shares=Number(trace.completed_shares||0),price=Number(trace.share_price??trace.gross_share_value??(shares?amount/shares:0)),matched=Number(trace.consumed_each_side||0);icon='BS';detail=`${matched.toFixed(2)} BP matched`;subtitle=`${shares.toFixed(2)} share${shares===1?'':'s'} × ${price.toFixed(2)} MIO`}
  else if(method==='single_line'){icon='P'+level;detail=['Level '+level,base+' BP',rate].filter(Boolean).join(' · ');subtitle=[member,code,pkg].filter(Boolean).join(' · ')}
  else if(['monthly_maintenance','annual_maintenance'].includes(method)){icon=method==='monthly_maintenance'?'MM':'AM';detail=['Generation '+level,base+(method==='monthly_maintenance'?' PPV':' MIO'),rate].filter(Boolean).join(' · ');subtitle=row.source_kind}
  else if(eco){icon='EC';const source=ecommerceSource(row);detail=[source.name,source.code,Number(row.base_points||0).toFixed(2)+(row.record_type==='maintenance_payout'?(row.reward_kind==='monthly_maintenance'?' PPV base':' MIO base'):' points')].filter(Boolean).join(' · ');subtitle=[row.order_code,row.product_name_snapshot].filter(Boolean).join(' · ')}
  return {icon,title,subtitle,detail,amount,time,state:row.status==='posted'?'Credited':held?'On hold':'Reversed',stateClass:row.status==='posted'?'credited':held?'hold':'other'};
 };
 return `<div class="earning-mobile-ledger">${[...groups].map(([day,items])=>`<section class="earning-mobile-day"><header><span>${displayHistoryDay(day)}</span><small>${items.length} ${items.length===1?'entry':'entries'}</small></header><div class="earning-mobile-entries">${items.map(row=>{const item=presentation(row);return `<article class="earning-mobile-entry"><span class="earning-mobile-icon ${esc(item.stateClass)}">${esc(item.icon)}</span><div class="earning-mobile-main"><div class="earning-mobile-title"><strong>${esc(item.title)}</strong><b>+${item.amount.toFixed(2)} <small>MIO</small></b></div><p>${esc(item.subtitle)}</p><footer><span>${esc(item.time)}</span><em class="${esc(item.stateClass)}">${esc(item.state)}</em><span>${esc(item.detail)}</span></footer></div></article>`}).join('')}</div></section>`).join('')}</div>`;
}
function mobileEarningWeekBounds(reference=new Date()){
 const today=historyDay(reference),cursor=new Date(today+'T00:00:00Z'),daysSinceFriday=(cursor.getUTCDay()+2)%7,currentStart=new Date(cursor);currentStart.setUTCDate(cursor.getUTCDate()-daysSinceFriday);const currentEnd=new Date(currentStart);currentEnd.setUTCDate(currentStart.getUTCDate()+7);const lastStart=new Date(currentStart);lastStart.setUTCDate(currentStart.getUTCDate()-7);const iso=date=>date.toISOString().slice(0,10);return {current:{start:iso(currentStart),end:iso(currentEnd)},last:{start:iso(lastStart),end:iso(currentStart)},total:{start:'',end:''}};
}
function mobileEarningCategory(row){if(['monthly_maintenance','annual_maintenance'].includes(row?.method))return row.method;if(row?.reward_kind)return'ecommerce';if(row?.method==='direct')return bonusDisplayLabel(row).startsWith('Welcome')?'welcome_bonus':'direct';return({generation:'generation',single_line:'single_line',binary_pool_share:'binary_pool_share'})[row?.method]||'other'}
function mobileEarningPeriodRows(rows,period=activeMobileEarningPeriod,reference=new Date()){if(period==='custom')return filterHistoryDates(rows,'earnings');const bounds=mobileEarningWeekBounds(reference)[period]||mobileEarningWeekBounds(reference).current;if(period==='total')return rows;return rows.filter(row=>{const day=historyDay(row.created_at);return day>=bounds.start&&day<bounds.end})}
function mobileEarningPeriodLabel(period=activeMobileEarningPeriod,reference=new Date()){const short=value=>new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));if(period==='custom'){const {from,to}=historyFilters.earnings;return from||to?`${from?short(from):'First record'} – ${to?short(to):'Today'}`:'Choose a date range'}if(period==='total')return'All recorded dates';const bounds=mobileEarningWeekBounds(reference)[period],last=new Date(bounds.end+'T00:00:00Z');last.setUTCDate(last.getUTCDate()-1);return`${short(bounds.start)} – ${short(last.toISOString().slice(0,10))}`}
function mobileEarningRangeCaption(){
 const {from,to}=historyFilters.earnings;if(!from&&!to)return '';
 const format=(value,includeYear=true)=>new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'long',...(includeYear?{year:'numeric'}:{}),timeZone:'UTC'}).format(new Date(value+'T00:00:00Z'));
 const label=from||to?`${from?format(from,!to||from.slice(0,4)!==to.slice(0,4)):'First record'} – ${to?format(to):'Today'}`:'All dates';
 return `<div class="mobile-earning-period"><strong role="status">${esc(label)}</strong>${from||to?'<button type="button" data-history-clear="earnings" aria-label="Clear earning date range" title="Show all dates">×</button>':''}</div>`;
}
function mobileEarningCycles(){
 const all=[...earningRows(),...(window.memberEcommerceRows||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),periodRows=filterHistoryDates(all,'earnings'),categories=[['direct','D','Direct sponsor'],['welcome_bonus','W','Welcome bonus'],['generation','G','Generation bonus'],['single_line','P','Binary placement'],['binary_pool_share','BS','Binary share'],['monthly_maintenance','MM','Monthly Maintenance'],['annual_maintenance','AM','Annual Maintenance'],['ecommerce','EC','E-commerce']],category=categories.find(item=>item[0]===activeMobileEarningCategory),selected=category?periodRows.filter(row=>mobileEarningCategory(row)===category[0]):periodRows,credited=selected.filter(row=>row.status==='posted');
 const header=`<section class="mobile-earning-toolbar"><div class="mobile-earning-total" aria-live="polite"><span>${category?'Selected bonus total':'Total earnings'}</span><strong>${sumEarnings(credited).toFixed(2)} <small>MIO</small></strong></div><div class="mobile-earning-filters">${earningRangeControl('earnings')}</div></section>${mobileEarningRangeCaption()}`;
 if(category){const paged=pagedHistory(selected,'earnings');return`<section class="mobile-earning-cycles">${header}<div class="mobile-earning-detail-head"><button type="button" data-mobile-earning-back aria-label="Back to earning categories">←</button><div><h3>${category[2]}</h3></div></div>${earningMobileLedger(paged,category[0])}${selected.length>20?historyPagination(selected.length,'earnings'):''}</section>`}
 return`<section class="mobile-earning-cycles">${header}<div class="mobile-earning-category-list">${categories.map(([key,icon,label])=>{const rows=periodRows.filter(row=>mobileEarningCategory(row)===key),posted=rows.filter(row=>row.status==='posted');return`<button type="button" class="mobile-earning-category" data-mobile-earning-category="${key}"><span class="mobile-category-icon">${icon}</span><span><strong>${label}</strong><small>${posted.length} credited ${posted.length===1?'entry':'entries'}</small></span><b>${sumEarnings(posted).toFixed(2)} <small>MIO</small></b><i>›</i></button>`}).join('')}</div></section>`;
}
document.addEventListener('click',event=>{const category=event.target.closest('[data-mobile-earning-category]');if(category){activeMobileEarningCategory=category.dataset.mobileEarningCategory;historyPage.earnings=1;renderEarningHistory();return}if(event.target.closest('[data-mobile-earning-back]')){activeMobileEarningCategory='all';historyPage.earnings=1;renderEarningHistory()}});
function openingEarningStatement(source='all'){const rows=(window.memberOpeningRows||[]).filter(r=>Number(r.amount)>0&&(source==='all'||(r.category==='manager'?'team_manager':r.category)===source||source==='team_bonus'&&['direct','generation','binary_pool_share','single_line','manager'].includes(r.category)));if(!rows.length)return '';const opening=rows.reduce((sum,r)=>sum+Number(r.amount),0),total=sourceAmount(source);return `<section class="dashboard-panel opening-earnings-statement"><h3>Opening earnings statement</h3><p>Previous system totals. Detailed transaction history begins with earnings on this system.</p><div class="management-fields">${rows.map(r=>`<div><span>${esc(({manager:'Manager',community_share:'Community Share',ecommerce:'E-commerce',other:'Other'})[r.category]||sourceLabel(r.category))}</span><strong>${Number(r.amount).toLocaleString('en-US',{maximumFractionDigits:4})} MIO</strong></div>`).join('')}</div><p><b>Opening: ${opening.toFixed(4)} MIO</b> · New: ${(total-opening).toFixed(4)} MIO · <b>Total: ${total.toFixed(4)} MIO</b></p></section>`;}
function renderEarningHistory(){
 const target=el('earningsTable');if(!target)return;
 el('earningSourceTabs')?.querySelectorAll('[data-earning-source]').forEach(button=>{const key=button.dataset.earningSource,active=key===activeEarningSource;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.innerHTML=`${esc(sourceLabel(key))}<b>${sourceAmount(key).toFixed(2)} MIO</b>`});
 const source=activeEarningSource;
 el('page-earnings').classList.toggle('earning-daily-mode',source==='all');
 const title=el('earningHistoryTitle'),hint=el('earningHistoryHint'),levels=el('earningLevelTabs'),ecom=el('earningEcommerceFilters');
 if(title)title.textContent=source==='ecommerce'?'E-commerce earnings':sourceLabel(source)+' history';
 if(ecom){ecom.hidden=source!=='ecommerce';ecom.classList.toggle('hidden',source!=='ecommerce');if(source==='ecommerce')ecom.innerHTML=renderEcommerceFilterTabs()}
 const allowed=earningLevels(source),showLevels=['generation','single_line'].includes(source)&&allowed.length>0;
 if(levels){levels.classList.toggle('hidden',!showLevels);levels.innerHTML=showLevels?`<span>Package levels</span><button class="${activeEarningLevel==='all'?'active':''}" data-earning-level="all">All levels</button>${allowed.map(n=>`<button class="${String(activeEarningLevel)===String(n)?'active':''}" data-earning-level="${n}">Level ${n}</button>`).join('')}`:''}
 if(source==='ecommerce'){if(hint)hint.textContent='Three shopping channels with separate credited and on-hold totals. Filter all sections by Pakistan date.';renderEcommerceRows(target);target.insertAdjacentHTML('afterbegin',openingEarningStatement('ecommerce'));return}
 let rows=[...earningRows()];
 if(source==='team_bonus')rows=rows.filter(x=>['direct','generation','binary_pool_share','single_line'].includes(x.method));else if(source!=='all')rows=rows.filter(x=>x.method===source);
 // E-commerce has its own page and is not added to network earnings.
 if(activeEarningStatus==='hold')rows=rows.filter(isHeldEarning);else if(activeEarningStatus==='credited')rows=rows.filter(x=>x.status==='posted');
 if(showLevels&&activeEarningLevel!=='all'&&allowed.includes(Number(activeEarningLevel)))rows=rows.filter(x=>Number(x.generation||1)===Number(activeEarningLevel));else if(!showLevels)activeEarningLevel='all';
 rows=filterHistoryDates(rows,'earnings').sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));
 if(hint)hint.textContent=source==='all'?'Daily network bonus summary. Open a date for its members; the period receipt is at the end.':source==='direct'?'Direct members, DP and the sponsor rate applied at the time of earning.':source==='binary_pool_share'?'Each distribution shows your shares, share price and matched BP.':['monthly_maintenance','annual_maintenance'].includes(source)?'Credited generation bonuses. Filter by date to view the earnings statement.':'Choose a level and date range to see its members and earning calculations.';
 const pagedRows=source==='all'?[]:pagedHistory(rows,'earnings');
 const desktop=source==='all'
  ? '<div id="desktopEarningHistory" class="earning-desktop-history"></div>'
  : `<div class="earning-desktop-controls">${historyDateControls('earnings')+earningPeriodSummary(rows)}</div><div class="earning-desktop-history">${earningDetailTable(pagedRows,source)}</div><div class="earning-desktop-pagination">${historyPagination(rows.length,'earnings')}</div><div class="earning-mobile-legacy">${earningMobileLedger(pagedRows,source)}</div>`;
 target.innerHTML=openingEarningStatement(source)+mobileEarningCycles()+desktop+totalEarningReceiptAction(rows,source);
 if(source==='all')renderDesktopEarnings();
 else enhanceResponsiveTables(target);
}

function earningLevels(source){if(source==='direct')return[1];const code=memberPackageCode||packages.find(p=>p.code===memberPackageCode)?.code;const plan=planRules?.plans?.[code];if(source==='generation'){const n=Number(plan?.max_generations??packages.find(p=>p.code===code)?.generations??1);return Array.from({length:Math.max(0,n-1)},(_,i)=>i+2)}if(source==='single_line'){const n=Number(plan?.single_line_levels??packages.find(p=>p.code===code)?.singleLevels??({BASIC_1:10,BASIC_2:15,ADVANCED_1:20,ADVANCED_2:25,PREMIUM:30}[code]||0));return Array.from({length:n},(_,i)=>i+1)}return[]}
function dateLabel(value){return value?new Date(value).toLocaleString():'—'}
function joiningDateLabel(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'long',year:'numeric'}).format(date)}
function ecommerceLevel(kind){return({sponsor:'Level 1',second_sponsor:'Level 2'})[kind]||''}
