const ecommercePages={normal:1,shopping_points:1,maintenance:1};
function ecommerceSection(row){return ['normal','shopping_points','maintenance'].includes(row.shopping_channel)?row.shopping_channel:'normal'}
function ecommerceSectionRows(kind){return filterHistoryDates(window.memberEcommerceRows||[],'earnings').filter(row=>ecommerceSection(row)===kind).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))}
function renderEcommerceFilterTabs(){return ecommerceSections.map(([key,label])=>{const rows=ecommerceSectionRows(key),credited=sumEarnings(rows.filter(x=>x.status==='posted'));return `<button type="button" class="ecommerce-filter-tab" data-ecommerce-section="${key}"><span>${esc(label)}</span><b>${credited.toFixed(2)} MIO credited · ${rows.length} entries</b></button>`}).join('')}
function renderEcommerceRows(target){if(!target)return;const all=filterHistoryDates(window.memberEcommerceRows||[],'earnings');target.innerHTML=historyDateControls('earnings')+earningPeriodSummary(all)+`<div class="ecommerce-section-list">${ecommerceSections.map(([kind,label,description])=>{const rows=ecommerceSectionRows(kind),credited=sumEarnings(rows.filter(x=>x.status==='posted')),held=sumEarnings(rows.filter(isHeldEarning)),pages=Math.ceil(rows.length/20)||1; ecommercePages[kind]=Math.min(Math.max(1,ecommercePages[kind]),pages);const paged=rows.slice((ecommercePages[kind]-1)*20,ecommercePages[kind]*20);return `<section class="ecommerce-history-section" id="ecommerce-section-${kind}"><header><div><span class="eyebrow">${kind==='normal'?'01':kind==='shopping_points'?'02':'03'} · Shopping channel</span><h3>${esc(label)}</h3><p>${esc(description)}</p></div><div class="ecommerce-section-totals"><strong>${credited.toFixed(2)} MIO <small>credited</small></strong><span>${held.toFixed(2)} MIO on hold · ${rows.length} entries</span></div></header><div class="earning-desktop-history">${earningDetailTable(paged,'ecommerce')}</div>${earningMobileLedger(paged,'ecommerce')}${rows.length>20?`<nav class="history-pagination" aria-label="${esc(label)} pages"><span>Page ${ecommercePages[kind]} of ${pages}</span><button type="button" class="btn small" data-ecommerce-page="${kind}" data-page-delta="-1" ${ecommercePages[kind]===1?'disabled':''}>Previous</button><button type="button" class="btn small" data-ecommerce-page="${kind}" data-page-delta="1" ${ecommercePages[kind]===pages?'disabled':''}>Next</button></nav>`:''}<div class="earning-total-action"><div><small>Selected period · ${rows.length} entries</small><strong>Credited ${credited.toFixed(2)} MIO</strong><span>On hold ${held.toFixed(2)} MIO · recorded separately</span></div><button class="btn primary" type="button" data-ecommerce-total="${kind}">Section receipt</button></div></section>`}).join('')}</div>`;enhanceResponsiveTables(target);const nav=el('earningEcommerceFilters');if(nav)nav.innerHTML=renderEcommerceFilterTabs()}
document.addEventListener('click',event=>{const section=event.target.closest('[data-ecommerce-section]');if(section){el('ecommerce-section-'+section.dataset.ecommerceSection)?.scrollIntoView({behavior:'smooth',block:'start'});return}const pager=event.target.closest('[data-ecommerce-page]');if(pager){const key=pager.dataset.ecommercePage;ecommercePages[key]+=Number(pager.dataset.pageDelta);renderEcommerceRows(el('earningsTable'));el('ecommerce-section-'+key)?.scrollIntoView({behavior:'smooth',block:'start'});return}const receipt=event.target.closest('[data-ecommerce-total]');if(receipt){showTotalEarningsReceipt(ecommerceSectionRows(receipt.dataset.ecommerceTotal),ecommerceSections.find(x=>x[0]===receipt.dataset.ecommerceTotal)?.[1]);return}});

function totalEarningReceiptAction(rows,source){const credited=sumEarnings(rows.filter(x=>x.status==='posted')),held=sumEarnings(rows.filter(isHeldEarning));return `<div class="earning-total-action"><div><small>Selected period · ${rows.length} entries</small><strong>Total credited: ${credited.toFixed(2)} MIO</strong><span>On hold: ${held.toFixed(2)} MIO · Held amounts are excluded from the credited total.</span></div><button type="button" class="btn primary" data-earning-total-receipt="${esc(source)}">Total earnings receipt</button></div>`}
function filteredEarningReceiptRows(){let rows=activeEarningSource==='ecommerce'?[...(window.memberEcommerceRows||[])]:[...earningRows()];if(activeEarningSource==='ecommerce'){if(activeEcommerceFilter==='credited')rows=rows.filter(x=>x.status==='posted');else if(activeEcommerceFilter==='hold')rows=rows.filter(isHeldEarning);else if(activeEcommerceFilter==='cashback')rows=rows.filter(x=>x.reward_kind==='cashback');else if(activeEcommerceFilter==='affiliate')rows=rows.filter(x=>x.reward_kind==='affiliate')}else{if(activeEarningSource==='team_bonus')rows=rows.filter(x=>['direct','generation','binary_pool_share','single_line'].includes(x.method));else if(activeEarningSource!=='all')rows=rows.filter(x=>x.method===activeEarningSource);if(activeEarningStatus==='hold')rows=rows.filter(isHeldEarning);else if(activeEarningStatus==='credited')rows=rows.filter(x=>x.status==='posted');if(['generation','single_line'].includes(activeEarningSource)&&activeEarningLevel!=='all')rows=rows.filter(x=>Number(x.generation||1)===Number(activeEarningLevel))}return filterHistoryDates(rows,'earnings')}
function showTotalEarningsReceipt(rowsOverride=null,sectionLabel='',dateFilter=historyFilters.earnings){if(!session)return;const rows=rowsOverride||filteredEarningReceiptRows(),credited=rows.filter(x=>x.status==='posted'),held=rows.filter(isHeldEarning),groups=new Map();for(const row of rows){const key=row.reward_kind?'ecommerce':row.method||'other',entry=groups.get(key)||{credited:[],held:[]};if(row.status==='posted')entry.credited.push(row);else if(isHeldEarning(row))entry.held.push(row);groups.set(key,entry)}const filter=dateFilter,period=filter.from||filter.to?`${filter.from||'First record'} to ${filter.to||'Today'}`:'All recorded dates',label=sectionLabel||sourceLabel(activeEarningSource),level=activeEarningLevel==='all'?'All eligible levels':'Level '+activeEarningLevel,lines=[...groups].map(([key,value])=>`<tr><th>${esc(sourceLabel(key))}</th><td>${value.credited.length+value.held.length}</td><td>${sumEarnings(value.credited).toFixed(2)}</td><td>${sumEarnings(value.held).toFixed(2)}</td></tr>`).join('');openHistoryDialog('Total earnings receipt',`${brandHeader('EARNINGS STATEMENT','Total earnings',label+' · '+period,'network')}<div class="receipt-statement-meta">${receiptGrid([{label:'Member',value:profile?.full_name||'Member'},{label:'Member code',value:profile?.member_code||'—',code:true},{label:'Period',value:period},{label:'Earning category',value:label},{label:'Level',value:level},{label:'Generated on',value:dateLabel(new Date())}])}</div><table class="receipt-statement-table"><thead><tr><th>Earning source</th><th>Entries</th><th>Credited MIO</th><th>On hold MIO</th></tr></thead><tbody>${lines||'<tr><td colspan="4">No earnings in this selection.</td></tr>'}</tbody><tfoot><tr><th>Total</th><td>${rows.length}</td><td>${sumEarnings(credited).toFixed(2)}</td><td>${sumEarnings(held).toFixed(2)}</td></tr></tfoot></table><div class="receipt-statement-total"><span>Total credited</span><strong>${sumEarnings(credited).toFixed(2)} MIO</strong></div><p class="receipt-footnote">This statement summarizes the selected earning history from your account ledger. On-hold rewards are shown separately and are not included in the credited total. It is not a cash payment receipt.</p>`)}
document.addEventListener('click',event=>{if(event.target.closest('[data-earning-total-receipt]'))showTotalEarningsReceipt()});
function renderMemberSummary(member,w,activations,points,bonuses){const eco=window.memberEcommerceRows||[],allBonuses=bonuses||[],held=allBonuses.filter(b=>b.status==='pending').reduce((n,b)=>n+Number(b.payable_amount),0),earned=allBonuses.filter(b=>b.status==='posted').reduce((n,b)=>n+Number(b.payable_amount),0),now=new Date(),monthEarned=allBonuses.filter(b=>{const date=new Date(b.created_at);return b.status==='posted'&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()}).reduce((n,b)=>n+Number(b.payable_amount),0);const active=(member?.status==='active'&&hasApprovedPackage)||isAdmin;el('memberSummary').innerHTML=`<div class="member-welcome"><div><small>My account</small><h2>${esc(member?.full_name||'Welcome')}</h2><p>${activations?.[0]?esc(planName(activations[0].package_code))+' package':active?'Company account':'Free registered account'}</p></div><span class="account-state ${active?'active':'waiting'}">${active?'Account active':'Package not active'}</span></div><div class="quick-actions"><button class="btn primary" data-page="${active?'earnings':'packages'}">${active?'View my earnings':'Activate a package'}</button><button class="btn" data-page="network">My team & links</button><button class="btn" data-page="orders">My orders</button></div>${!active?'<p class="note">You can share referral and product links. Direct earnings stay on hold until you activate a package.</p>':''}`;el('earningOverview').innerHTML=`<section class="earning-premium-overview"><button type="button" class="earning-overview-total" data-earning-source="all" data-earning-status="credited"><span>Total credited earnings</span><small><i></i> Ledger verified</small><strong>${earned.toFixed(2)} <em>MIO</em></strong></button><div class="earning-overview-stats"><div><span>This month</span><b>${monthEarned.toFixed(2)} MIO</b></div><button type="button" data-earning-source="all" data-earning-status="hold"><span>On hold</span><b>${held.toFixed(2)} MIO</b></button></div></section>`}


function mioActionLabel(action){return({transfer_in:'MIO Points received',transfer_out:'MIO Points sent',admin_mint:'Company added MIO Points',admin_burn:'Company removed MIO Points',package_activation:'Plan activation payment'})[action]||String(action||'Wallet activity').replaceAll('_',' ')}
function openHistoryDialog(title,body,printable=false){let d=document.getElementById('historyRecordDialog');if(!d){d=document.createElement('dialog');d.id='historyRecordDialog';d.className='history-record-dialog';document.body.append(d)}d.innerHTML=`<div class="record-toolbar"><h2>${esc(title)}</h2><div><button class="btn small print-record" type="button">Print / Save PDF</button> <button class="btn small close-record" type="button">Close</button></div></div><div class="record-print-area">${body}</div>`;d.querySelector('.close-record').onclick=()=>d.close();d.querySelector('.print-record').onclick=()=>{document.body.classList.add('printing-record');window.print();setTimeout(()=>document.body.classList.remove('printing-record'),500)};if(!d.open){if(typeof d.showModal==='function')d.showModal();else d.setAttribute('open','')}return d}
function brandHeader(kind,title,subtitle,theme='network'){return `<div class="receipt-brand receipt-theme-${esc(theme)}"><img src="/market-is-online-logo.png" alt="Market is Online"><div><span>${esc(kind)}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div></div>`}
function receiptGrid(fields){return `<dl class="receipt-grid receipt-detail-grid">${fields.filter(Boolean).map(f=>`<div class="${f.wide?'wide':''}"><dt>${esc(f.label)}</dt><dd class="${f.amount?'receipt-amount':''} ${f.code?'code':''}">${f.html??esc(f.value??'—')}</dd></div>`).join('')}</dl>`}
function receiptParty(x){return x.source_name?`<strong>${esc(x.source_name)}</strong><small>${esc(x.source_code||'Member code unavailable')}</small>`:'Member details unavailable'}
function earningState(x){return x.status==='posted'?'Credited to your wallet':x.status==='pending'?'On hold · not yet withdrawable':'Reversed earning'}
async function loadMioReceipt(row){let info={};if(row.transfer_id&&row.action.startsWith('transfer_')){const {data,error}=await db.rpc('lookup_mio_transfer_receipt',{p_transfer_id:row.transfer_id});if(error)throw error;info=Array.isArray(data)?data[0]||{}:data||{}}showMioReceipt(row,info)}
function showMioReceipt(x,info={}){const code=x.transfer_id||x.id;const sent=x.action==='transfer_out';const own=profile||{};const cp=info.sender_id?{sender:{full_name:info.sender_name,member_code:info.sender_code},recipient:{full_name:info.recipient_name,member_code:info.recipient_code}}:{};const from=cp.sender||(sent?own:{}),to=cp.recipient||(sent?{}:own);const party=(p,idFallback)=>`<strong>${esc(p?.full_name||'Member')}</strong><small>${esc(p?.member_code||idFallback||'Member code unavailable')}</small>`;const transfer=x.action.startsWith('transfer_');openHistoryDialog(transfer?'MIO Points Transfer Receipt':'MIO Wallet Transaction',`${brandHeader('WALLET RECEIPT',transfer?'Points transfer':'Wallet transaction',transfer?'MIO Points recorded between member wallets':'Recorded activity in your MIO wallet')}<dl class="receipt-grid"><div><dt>Receipt reference</dt><dd class="code">${esc(code)}</dd></div><div><dt>Date and time</dt><dd>${new Date(x.created_at).toLocaleString()}</dd></div>${transfer?`<div><dt>Sent by</dt><dd>${party(from,info.sender_id||(sent?session?.user.id:x.counterparty_id))}</dd></div><div><dt>Received by</dt><dd>${party(to,info.recipient_id||(sent?x.counterparty_id:session?.user.id))}</dd></div>`:`<div><dt>Activity</dt><dd>${esc(mioActionLabel(x.action))}</dd></div>`}<div><dt>Points</dt><dd class="receipt-amount">${Math.abs(Number(x.amount)).toFixed(2)} MIO</dd></div><div><dt>Direction</dt><dd>${Number(x.amount)>0?'Added to your wallet':'Removed from your wallet'}</dd></div>${x.reason?`<div class="wide"><dt>Note</dt><dd>${esc(x.reason)}</dd></div>`:''}</dl><p class="receipt-footnote">This is a digital MIO Points ledger receipt. It does not confirm a separate PKR cash payment.</p>`)}
function showPointDetails(x){const source=x.source_order_id?'Shopping order reference':x.source_activation_id?'Plan activation reference':'Recorded point entry';openHistoryDialog('Point transaction details',`${brandHeader('POINTS RECEIPT',`${Number(x.amount)>0?'+':''}${Number(x.amount).toFixed(2)} ${esc(x.point_type||'Points')}`,`${esc(x.entry_kind||'Recorded transaction')}${x.side?' · '+esc(x.side)+' side':''}`)}<dl class="receipt-grid"><div><dt>Point type</dt><dd>${esc(x.point_type)}</dd></div><div><dt>Transaction</dt><dd>${esc(x.entry_kind)}</dd></div><div><dt>Date</dt><dd>${new Date(x.created_at).toLocaleString()}</dd></div><div><dt>Reference type</dt><dd>${source}</dd></div><div class="wide"><dt>Reference</dt><dd class="code">${esc(x.source_order_id||x.source_activation_id||'Recorded transaction')}</dd></div></dl><p class="receipt-footnote">This receipt shows the points ledger entry in your account.</p>`)}
