function syncUserReferral(){const code=currentSellingCode();const field=el('referralCode'),label=document.querySelector('label[for="referralCode"]');if(!field)return;if(code){field.value=shoppingAccount.userCode(code);field.readOnly=true;field.dataset.userReferral='true';if(label)label.textContent='User referral code';const helper=field.closest('.field').querySelector('.helper');if(helper)helper.textContent='Automatically linked from the member’s User referral link.';db.rpc('shopping_referral',{p_code:code}).then(({data,error})=>{if(error||!data){el('signupSponsor').textContent='This referral will be checked when you create your account.';return;}field.value=data.code;el('signupSponsor').textContent='Linked member: '+data.name+' · Shopping User registration';});}}
syncUserReferral();applyVendorRegistrationVisibility();
if(sellingQuery.get('vendor'))sessionStorage.setItem('mio-vendor-invite',sellingQuery.get('vendor'));
function currentSellingCode(){try{const a=JSON.parse(sessionStorage.getItem('mio-selling-link')||'null');if(!a||a.expires<Date.now())return '';return shoppingAccount?.userCode(a.code)===shoppingAccount?.userCode(profile?.member_code)?'':a.code}catch{return ''}}
function planName(code){return ({BASIC_1:'Starter',BASIC_2:'Basic',ADVANCED_1:'Silver',ADVANCED_2:'Gold',PREMIUM:'Platinum'})[code]||'Free account'}
function sellingLinks(){if(!profile)return '';const url=new URL(location.origin+location.pathname);url.searchParams.set('affiliate',shoppingAccount.userCode(profile.member_code));url.hash='shop';const vendor=new URL(location.origin+location.pathname);vendor.searchParams.set('vendor',profile.member_code);vendor.hash='vendor-register';return `<div class="selling-links"><h3>Selling & vendor invitations</h3><p>Your affiliate link opens the marketplace. Shoppers create a User account and can request your refundable order hold. Network membership is a separate choice.</p><button class="btn primary copy-code" data-copy="${esc(url.href)}">Copy User referral link</button> <button class="btn copy-code" data-copy="${esc(vendor.href)}">Copy vendor invitation</button><p class="helper">Sponsor hold orders need your approval. Security is 2 MIO up to PKR 6,000; above that, 10% of the order value is converted at the order rate. The hold returns after delivery and confirmed payment.</p></div>`}
function productRewardText(p,quantity=1){const base=Number(p.ppv_per_unit||0);if(currentSellingCode())return '<strong class="ppv-callout">Affiliate reward goes to the seller</strong><small class="ppv-help">Your product discount is shown above.</small>';const mio=profile?.shopping_reward_mode==='MIO'&&hasApprovedPackage,amount=mio?((Math.trunc(base*.70*10000)/10000)*quantity).toFixed(2):(base*quantity).toFixed(2),unit=mio?'MIO cashback':'PPV';return `<strong class="ppv-callout">${amount} ${unit}</strong><small class="ppv-help">Credited after delivery and confirmed payment.</small>`}
