window.memberEcommerceRows=personal;el('ecommerceSummary').innerHTML=summary;if(isAdmin){el('ecommerceRows').innerHTML=table;el('adminEcommerce').innerHTML=summary+'<div class="table-wrap section">'+table+'</div>'}else renderEcommerceRows(el('ecommerceRows'),activeEcommerceFilter);renderEarningHistory();
el('ecommercePPV').innerHTML='<h2>PPV shopping & affiliate orders</h2>'+((report.ppv_orders||[]).map(o=>`<div class="list-row"><div><strong>${esc(o.order_code)}</strong><small>${o.selling_affiliate_id?'Affiliate sale':'Self shopping'} · ${orderStatus(o.status)}</small></div><b>${Number(o.rewards_credited_at?o.ppv_generated:['cancelled','returned'].includes(o.status)?0:o.reward_ppv_total).toFixed(2)} PPV · ${o.rewards_credited_at?'credited':['cancelled','returned'].includes(o.status)?'cancelled':'on hold'}</b></div>`).join('')||'<p>Your PPV-mode purchases and attributed affiliate sales will appear here.</p>');
el('ecommerceTop').innerHTML=isAdmin?'<h2>Top e-commerce earners</h2>'+((report.top_earners||[]).map(r=>`<div class="list-row"><span>${esc(r.full_name)} · ${esc(r.member_code)}</span><b>${Number(r.income).toFixed(2)} MIO</b></div>`).join('')||'<p>No credited earnings yet.</p>'):'';
const eligible=report.eligible??hasApprovedPackage,ppvUsed=Number(report.shopping_ppv_used)||0,ppvCap=Number(report.shopping_ppv_cap)||110,ppvLocked=!!report.shopping_ppv_locked||ppvUsed>=ppvCap;const mode=ppvLocked?'MIO':(report.mode||profile?.shopping_reward_mode||'PPV');
