function sizeTreePanSurface(){const visual=el('networkVisual'),surface=visual?.querySelector('.tree-pan-surface');if(!surface)return null;const viewWidth=Math.max(1,visual.clientWidth||visual.getBoundingClientRect().width||1),viewHeight=Math.max(1,visual.clientHeight||visual.getBoundingClientRect().height||1),scaledWidth=treeBaseSize.width*treeZoom,scaledHeight=treeBaseSize.height*treeZoom;surface.style.width=`${Math.max(viewWidth,scaledWidth+viewWidth)}px`;surface.style.height=`${Math.max(viewHeight,scaledHeight+viewHeight)}px`;return surface}
function setTreeZoom(next,anchorX=null,anchorY=null){const visual=el('networkVisual'),svg=visual.querySelector('svg.genealogy-canvas'),surface=visual.querySelector('.tree-pan-surface'),old=treeZoom;if(!svg||!surface||!treeBaseSize.width)return;const rect=visual.getBoundingClientRect(),x=anchorX??rect.width/2,y=anchorY??rect.height/2,oldCentreX=surface.offsetWidth/2,oldCentreY=surface.offsetHeight/2,logicalX=(visual.scrollLeft+x-oldCentreX)/old,logicalY=(visual.scrollTop+y-oldCentreY)/old;treeZoom=Math.max(.02,Math.min(10,next));svg.style.width=`${treeBaseSize.width*treeZoom}px`;svg.style.height=`${treeBaseSize.height*treeZoom}px`;sizeTreePanSurface();visual.scrollLeft=Math.max(0,surface.offsetWidth/2+logicalX*treeZoom-x);visual.scrollTop=Math.max(0,surface.offsetHeight/2+logicalY*treeZoom-y)}
function centerTreeInViewport(rootPoint=null){const visual=el('networkVisual'),surface=visual?.querySelector('.tree-pan-surface');if(!surface)return;requestAnimationFrame(()=>{if(!surface.isConnected)return;sizeTreePanSurface();const viewWidth=Number(visual.clientWidth)||visual.getBoundingClientRect().width||0,viewHeight=Number(visual.clientHeight)||visual.getBoundingClientRect().height||0;const left=rootPoint?surface.offsetWidth/2+(rootPoint.x-treeBaseSize.width/2)*treeZoom-viewWidth/2:(surface.offsetWidth-viewWidth)/2;const top=rootPoint?surface.offsetHeight/2+(rootPoint.y-treeBaseSize.height/2)*treeZoom-32:(surface.offsetHeight-viewHeight)/2;visual.scrollLeft=Number.isFinite(left)?Math.max(0,left):0;visual.scrollTop=Number.isFinite(top)?Math.max(0,top):0;})}
