function drawNetwork(nodes,kind,data={}){
 treeNodes=nodes;treeRootPoint=null;treeBaseSize={width:0,height:0};
 if(!el('treeMemberDetails').children.length)el('treeMemberDetails').innerHTML='<div class="tree-detail-empty"><span>i</span><strong>Select a member</strong><small>Member and team details will appear here.</small></div>';
 el('treeLegend').innerHTML=packages.map(p=>`<span><i style="background:${packageColour(p.code)}"></i>${esc(planName(p.code))}</span>`).join('')+'<span><i style="background:#82938d"></i>Free</span>';
 if(!nodes.length){el('networkVisual').innerHTML='<p>No members or vendors in this tree yet.</p>';return}
 const binary=['binary','single_line'].includes(kind),map=new Map(nodes.map(n=>[n.id,n])),children=new Map();
 for(const n of nodes){if(n.parent_id&&map.has(n.parent_id)){if(!children.has(n.parent_id))children.set(n.parent_id,[]);children.get(n.parent_id).push(n)}}
 const roots=nodes.filter(n=>!n.parent_id||!map.has(n.parent_id)),widths=new Map(),positions=new Map();let maxDepth=0;
 const orderedBinaryChildren=n=>['LEFT','RIGHT'].map(side=>(children.get(n.id)||[]).find(k=>k.side===side)).filter(Boolean);
 function measure(n,seen=new Set()){if(seen.has(n.id))return 178;seen=new Set(seen).add(n.id);const kids=children.get(n.id)||[];let width=178;if(kids.length){if(binary){const ordered=orderedBinaryChildren(n);width=ordered.length===1?Math.max(178,measure(ordered[0],seen)):ordered.reduce((v,k)=>v+measure(k,seen),0)}else width=kids.reduce((v,k)=>v+measure(k,seen),0)}widths.set(n.id,width);return width}roots.forEach(n=>measure(n));
 function place(n,left,depth=0){if(positions.has(n.id))return;const width=widths.get(n.id)||178;positions.set(n.id,{x:left+width/2,y:depth*142+72});maxDepth=Math.max(maxDepth,depth);let cursor=left;const kids=children.get(n.id)||[];if(binary&&kids.length){const ordered=orderedBinaryChildren(n);if(ordered.length===1)place(ordered[0],left,depth+1);else for(const k of ordered){place(k,cursor,depth+1);cursor+=widths.get(k.id)||178}}else for(const k of kids){place(k,cursor,depth+1);cursor+=widths.get(k.id)||178}}
 let totalWidth=0;for(const n of roots){place(n,totalWidth);totalWidth+=widths.get(n.id)||178}const contentWidth=totalWidth;totalWidth=Math.max(760,totalWidth);if(contentWidth<totalWidth){const shift=(totalWidth-contentWidth)/2;for(const pos of positions.values())pos.x+=shift}const height=(maxDepth+1)*142+170;treeBaseSize={width:totalWidth,height};treeRootPoint=positions.get(roots[0]?.id)||null;
 const line=(a,b,label='')=>`<path d="M${a.x},${a.y+96} V${a.y+116} H${b.x} V${b.y}" fill="none" stroke="#9dafaa" stroke-width="1.5"/>${label?`<text x="${b.x+5}" y="${b.y-5}" fill="#587366" font-size="10">${label}</text>`:''}`;
 let svg='';for(const n of nodes){const b=positions.get(n.id),a=positions.get(n.parent_id);if(a&&b)svg+=line(a,b,binary?(n.side==='LEFT'?'L':'R'):'')}
 for(const n of nodes){const pos=positions.get(n.id);if(!pos)continue;const colour=packageColour(n.package),variant=(Array.from(String(n.id)).reduce((sum,ch)=>sum+ch.charCodeAt(0),0)%10)+1,avatar=safeImage(n.profile_photo_url)||memberAvatar(n.gender),rankBadgeImage=safeImage(n.rank_badge_url),selected=n.id===selectedTreeNodeId,packageMatch=!activeTreeFilter.package||n.package===activeTreeFilter.package,statusMatch=!activeTreeFilter.status||String(n.status||'').toLowerCase()===activeTreeFilter.status;svg+=`<foreignObject x="${pos.x-68}" y="${pos.y}" width="136" height="112"><div xmlns="http://www.w3.org/1999/xhtml" class="visual-node ${selected?'selected':''} ${n.breakaway?'manager-breakaway':''} ${packageMatch&&statusMatch?'':'tree-filter-dim'}" style="--package-colour:${colour}"><span class="tree-rank-label">${nodeRankStickers(n)}</span><button class="visual-person" data-tree-info="${esc(n.id)}" aria-label="View ${esc(n.full_name)} details"><span class="tree-avatar-picture"><img src="${avatar}" alt="${esc(n.full_name)} profile picture">${rankBadgeImage?`<img class="tree-rank-picture" src="${rankBadgeImage}" alt="${esc(n.rank_name||n.rank||'Leadership rank')} badge">`:''}</span><strong>${esc(n.full_name)}</strong><small>${countryFlag(n.country_code)} ${esc(n.node_type==='vendor'?(n.business_name||'Vendor'):n.member_code||'Member')}</small><span class="tree-plan-label">${n.breakaway?'Breakaway Manager':esc(n.node_type==='vendor'?'Vendor':planName(n.package))}</span></button></div></foreignObject>`}
 el('networkVisual').innerHTML=`<div class="tree-pan-surface"><svg class="genealogy-canvas" role="img" aria-label="${esc(kind)} network tree" width="${totalWidth}" height="${height}" viewBox="0 0 ${totalWidth} ${height}" style="width:${totalWidth*treeZoom}px;height:${height*treeZoom}px">${svg}</svg>${data.truncated?'<p class="tree-truncated">500 members shown. Search by code or open a member profile to continue.</p>':''}</div>`;sizeTreePanSurface();focusTreeRoot();
}
