function countrySelectOptions(value){return '<option value="">Select country</option>'+COUNTRY_CODES.map(code=>({code,name:countryName(code)})).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.code}" ${c.code===value?'selected':''}>${countryFlag(c.code)} ${esc(c.name)}</option>`).join('')}
function productCountryEditor(product){return `<form class="product-country-editor" data-product="${product.id}"><label>Product country<select name="country" required>${countrySelectOptions(product.country_code)}</select></label><button class="btn" type="submit">Save country</button></form>`}
async function loadCountryMaintenanceControls(){const host=document.getElementById('countryMaintenanceControls');if(!host||!isAdmin)return;const {data,error}=await db.rpc('admin_monthly_countries');if(error)throw error;const states=new Map((Array.isArray(data)?data:[]).map(r=>[r.country_code,r.enabled]));host.innerHTML=`<div><span class="eyebrow">Country controls</span><h3>Monthly maintenance by country</h3><p>Turn monthly maintenance on or off for each member country. Annual maintenance stays separate.</p></div><form id="countryMaintenanceForm"><label>Country<select name="country" required>${countrySelectOptions('PK')}</select></label><label class="country-status-toggle"><input name="enabled" type="checkbox"> Monthly maintenance enabled</label><button class="btn primary" type="submit">Save country setting</button><p role="status" class="country-maintenance-status"></p></form>`;const form=host.querySelector('form'),country=form.elements.country,enabled=form.elements.enabled,status=host.querySelector('[role=status]');const sync=()=>{enabled.checked=states.get(country.value)!==false;status.textContent=enabled.checked?'Monthly maintenance is ON for this country.':'Monthly maintenance is OFF for this country.'};country.onchange=sync;sync();form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const code=country.value,on=enabled.checked;await confirmSensitive('Turn monthly maintenance '+(on?'ON':'OFF')+' for '+countryName(code)+'. Annual maintenance will stay unchanged.');const {error}=await db.rpc('admin_set_monthly_country',{p_country:code,p_enabled:on});if(error)throw error;states.set(code,on);sync();toast('Country maintenance setting saved')})}}
document.addEventListener('submit',e=>{if(!e.target.matches('.product-country-editor'))return;e.preventDefault();const form=e.target;submit(form,async()=>{const {error}=await db.rpc('admin_set_product_country',{p_product:form.dataset.product,p_country:form.elements.country.value});if(error)throw error;toast('Product country updated');await loadAdmin()})});

