async function saveNetworkMioPrice(price){
 if(!isAdmin)throw Error('Admin access required');
 if(!Number.isFinite(price)||price<=0||price>1000000||Math.abs(price*100-Math.round(price*100))>1e-6)throw Error('Enter a valid PKR price with up to two decimals');
 await confirmSensitive('Set MIO price to '+money(price)+' for new shopping calculations');
 const {data,error}=await db.rpc('admin_set_mio_reference_price',{p_price:price});if(error)throw error;
 mioReferencePricePkr=Number(data.price_pkr);updateMioReferencePrice();await loadCatalog();
}

