// Only fetch the currently requested page. Shared startup verifies identity/access only.
const pageLoads=new Map();
function loadRequestedPage(name){
 const key=(session?.user.id||'guest')+':'+name;if(pageLoads.has(key))return pageLoads.get(key);
 const task=Promise.resolve().then(async()=>{
  const uid=session?.user.id;
  if(['shop','vendors','categories','bundles'].includes(name)||/^(vendor|category|product)\//.test(name))return loadCatalog();
  if(name==='packages')return Promise.all([loadPlanCatalog(),loadOfflineInstructions(),uid?loadPlatinumPurchases():Promise.resolve()]);
  if(name==='vendor-register'){await loadVendorRegistrationSetting();return vendorPortal?.registration()}
  if(!uid){if(name==='sell')return vendorPortal?.referrals();if(name==='orders')return loadGuestOrders();return}
  if(name==='shopping'||name==='account'||name.startsWith('account/'))return shoppingAccount.refresh();
  if(name==='dashboard')return loadDashboardFinancial();
  if(name==='transactions')return window.MioCashHistory?.refresh();
  if(name==='exchange')return window.MioExchange?.refresh();
  if(name==='profile')return window.MioDashboard?.refresh(name);
  if(name==='wallet'||name==='transfer')return loadWalletPage();
  if(name==='network'||name==='network-graphical'){await loadNetworkViews();if(name==='network-graphical')return;vendorPortal?.networkInvite();return Promise.all([loadGenerationLevels(),shoppingAccount.membershipQueue(false)]);}
  if(name==='earnings')return loadEarningsPage();
  if(name==='ecommerce')return loadEcommerce();
  if(name==='orders'){let history=el('oldShoppingHistory');if(shoppingAccount.hasCustomer&&!history){history=document.createElement('button');history.id='oldShoppingHistory';history.className='btn';history.dataset.page='account/orders';history.textContent='My shopping account';el('ordersTable').before(history)}const {data,error}=await db.from('orders').select('*,order_items(*)').eq('buyer_id',uid).order('created_at',{ascending:false}).limit(50);if(error)throw error;const context=await orderContexts(data||[]);if(session?.user.id!==uid)return;renderMemberOrders(data||[],context);window.MioDashboard?.setOrderNotifications(data||[]);return loadAffiliateOrderApprovals()}
  if(name==='sell')return vendorPortal?.referrals();
  if(name==='seller')return vendorPortal?.refresh();
 }).catch(e=>{console.warn('Page refresh failed',name,e);toast('Could not refresh this page. Please try again.')}).finally(()=>pageLoads.delete(key));pageLoads.set(key,task);return task;
}
async function loadDashboardFinancial(){
 const uid=session?.user.id;if(!uid)return;
 const [wallet,points,bonuses,maintenance]=await Promise.all([db.from('mio_wallet_accounts').select('balance').eq('member_id',uid).maybeSingle(),fetchAll('point_ledger','point_type,amount,idempotency_key',uid,'member_id'),fetchAll('bonus_transactions','method,payable_amount,status',uid,'beneficiary_id'),loadMaintenanceEarnings(uid)]);
 if(wallet.error)throw wallet.error;if(session?.user.id!==uid)return;
 const net=points.filter(x=>x.point_type==='PPV').reduce((n,x)=>n+Number(x.amount),0),adjustment=points.filter(x=>x.point_type==='PPV'&&Number(x.amount)<0&&String(x.idempotency_key||'').startsWith('unified-total-ppv-cap:')).reduce((n,x)=>n-Math.min(0,Number(x.amount)),0),total=Math.max(0,net+adjustment),ppv=Math.min(110,Math.max(0,net));
 const opening=(window.memberAccountBaseline?.opening_earnings||[]).map(x=>({status:'posted',payable_amount:x.amount})),all=[...bonuses,...maintenance,...opening];
 window.MioDashboard?.setRewardPreference({eligible:hasApprovedPackage,mode:profile?.shopping_reward_mode||'PPV',ppvUsed:ppv,ppvCap:110,locked:ppv>=110});
 window.MioDashboard?.setFinancial({balance:Number(wallet.data?.balance||0),ppv,ppvExcess:Math.max(0,total-110),ppvTotal:total,earned:all.filter(x=>x.status==='posted').reduce((n,x)=>n+Number(x.payable_amount),0),held:all.filter(x=>x.status==='pending').reduce((n,x)=>n+Number(x.payable_amount),0)});
}
async function loadWalletPage(){
 const uid=session?.user.id;if(!uid)return;
 const [wallet,points]=await Promise.all([db.from('mio_wallet_accounts').select('balance').eq('member_id',uid).maybeSingle(),fetchAll('point_ledger','id,point_type,amount,entry_kind,side,created_at,source_order_id,source_activation_id,idempotency_key',uid,'member_id')]);
 if(wallet.error)throw wallet.error;if(session?.user.id!==uid)return;
 const ppv=Math.min(110,Math.max(0,points.filter(x=>x.point_type==='PPV').reduce((n,x)=>n+Number(x.amount),0)));el('mioBalance').textContent=String(wallet.data?.balance||0);el('ppvBalance').textContent=ppv.toFixed(2);el('currentPackage').textContent=planName(memberPackageCode);window.memberPpvRows=points.filter(x=>x.point_type==='PPV');window.memberOtherPointRows=points.filter(x=>x.point_type!=='PPV');renderCompactPointActivity();window.MioDashboard?.setFinancial({balance:Number(wallet.data?.balance||0),ppv});
}
